import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';

interface PublicRouteProps {
  /** Route chỉ dành cho người chưa đăng nhập.
   *  Nếu đã xác thực → redirect về trang gốc (state.from) hoặc mặc định /tickets */
  children: React.ReactNode;
  /** Đường dẫn fallback khi đã đăng nhập, mặc định là /tickets */
  redirectTo?: string;
}

/**
 * PublicRoute — bảo vệ các route công khai (login, register, …).
 *
 * Logic:
 *  - Chưa đăng nhập  → hiển thị children bình thường
 *  - Đã đăng nhập    → redirect tới `redirectTo` (mặc định: `/tickets`)
 *
 * Nhận ưu tiên đường dẫn từ `location.state.from` khi có (ví dụ:
 * người dùng bị ProtectedRoute đẩy về /login, state.from lưu URL gốc).
 */
export const PublicRoute: React.FC<PublicRouteProps> = ({
  children,
  redirectTo = '/dashboard',
}) => {
  const { isAuthenticated } = useAppSelector((state) => state.auth);
  const location = useLocation();

  if (isAuthenticated) {
    // Nếu trước đó bị redirect từ một trang cụ thể, quay về trang đó
    const from =
      (location.state as { from?: Location })?.from?.pathname || redirectTo;

    return <Navigate to={from} replace />;
  }

  return <>{children}</>;
};
