import React, { useState } from 'react';
import { Modal } from '../../../components/common/Modal';
import { Button } from '../../../components/common/Button';
import { TextArea } from '../../../components/common/TextArea';
import styles from './WorkflowModal.module.css';

interface CancelTaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (reason: string) => Promise<void>;
  taskTitle: string;
}

export const CancelTaskModal: React.FC<CancelTaskModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  taskTitle,
}) => {
  const [reason, setReason] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reason.trim()) return;

    setSubmitting(true);
    try {
      await onSubmit(reason.trim());
      handleClose();
    } catch (error) {
      console.error('Failed to cancel task:', error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setReason('');
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Hủy task" size="md">
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.taskInfo}>
          <span className={styles.label}>Task:</span>
          <span className={styles.value}>{taskTitle}</span>
        </div>

        <div className={styles.dangerAlert}>
          <i className="fas fa-times-circle"></i>
          <span>
            <strong>Cảnh báo:</strong> Hành động này không thể hoàn tác. Task sẽ bị hủy và không
            tính vào KPI.
          </span>
        </div>

        <div className={styles.formGroup}>
          <label htmlFor="reason" className={styles.label}>
            Lý do hủy task <span className={styles.required}>*</span>
          </label>
          <TextArea
            id="reason"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            placeholder="Ví dụ: Yêu cầu không còn cần thiết, trùng lặp với task khác, thay đổi ưu tiên..."
            rows={4}
            required
            disabled={submitting}
          />
          <span className={styles.hint}>Lý do hủy sẽ được ghi lại trong lịch sử task</span>
        </div>

        <div className={styles.actions}>
          <Button type="button" variant="secondary" onClick={handleClose} disabled={submitting}>
            Quay lại
          </Button>
          <Button type="submit" variant="danger" disabled={!reason.trim() || submitting}>
            {submitting ? 'Đang hủy...' : 'Xác nhận hủy task'}
          </Button>
        </div>
      </form>
    </Modal>
  );
};
