import React, { useEffect, useState } from 'react';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchSLAAlerts,
  fetchSLAStats,
  escalateAlert,
  reassignAlert,
  fetchCandidateSuggestions,
  setFilters,
  updateCountdowns,
} from '../../store/slices/slaAlertsSlice';
import { SLAAlert, SLAAlertType } from '../../models/SLAAlert';
import { AlertCard } from '../../components/sla-alerts/AlertCard';
import { AlertsStatsCards } from '../../components/sla-alerts/AlertsStatsCards';
import { AlertsFilters } from '../../components/sla-alerts/AlertsFilters';
import {
  EscalateModal,
  ReassignModal,
} from '../../components/sla-alerts/AlertActionModals';
import './SLAAlertsPage.css';

export const SLAAlertsPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const {
    items,
    stats,
    candidates,
    filters,
    loading,
    statsLoading,
    candidatesLoading,
    actionLoading,
    error,
  } = useAppSelector((state) => state.slaAlerts);

  const [selectedAlert, setSelectedAlert] = useState<SLAAlert | null>(null);
  const [isEscalateModalOpen, setIsEscalateModalOpen] = useState(false);
  const [isReassignModalOpen, setIsReassignModalOpen] = useState(false);

  useEffect(() => {
    dispatch(fetchSLAStats());
    dispatch(fetchSLAAlerts({ filters }));
  }, [dispatch, filters]);

  // Update countdowns every second
  useEffect(() => {
    const interval = setInterval(() => {
      dispatch(updateCountdowns());
    }, 1000);

    return () => clearInterval(interval);
  }, [dispatch]);

  const handleFiltersChange = (newFilters: typeof filters) => {
    dispatch(setFilters(newFilters));
  };

  const handleEscalate = (alert: SLAAlert) => {
    setSelectedAlert(alert);
    setIsEscalateModalOpen(true);
  };

  const handleReassign = async (alert: SLAAlert) => {
    setSelectedAlert(alert);
    // Fetch candidate suggestions
    await dispatch(fetchCandidateSuggestions({ alertId: alert.id }));
    setIsReassignModalOpen(true);
  };

  const handleEscalateConfirm = async (
    alertId: string,
    reason: string,
    escalateTo?: string
  ) => {
    try {
      await dispatch(escalateAlert({ alertId, reason, escalateTo })).unwrap();
      setIsEscalateModalOpen(false);
      setSelectedAlert(null);
      // Refresh data
      dispatch(fetchSLAStats());
      dispatch(fetchSLAAlerts({ filters }));
    } catch (err) {
      console.error('Failed to escalate alert:', err);
    }
  };

  const handleReassignConfirm = async (
    alertId: string,
    relatedId: string,
    type: SLAAlertType,
    newAssigneeId: string,
    newAssigneeName: string,
    reason: string
  ) => {
    try {
      await dispatch(
        reassignAlert({
          alertId,
          relatedId,
          type,
          newAssigneeId,
          newAssigneeName,
          reason,
        })
      ).unwrap();
      setIsReassignModalOpen(false);
      setSelectedAlert(null);
      // Refresh data
      dispatch(fetchSLAStats());
      dispatch(fetchSLAAlerts({ filters }));
    } catch (err) {
      console.error('Failed to reassign alert:', err);
    }
  };

  return (
    <div className="sla-alerts-page">
      <div className="sla-alerts-page__header">
        <div className="sla-alerts-page__title-row">
          <h1 className="sla-alerts-page__title">Cảnh báo SLA</h1>
          <span className="sla-alerts-page__subtitle">
            Theo dõi và xử lý các cảnh báo vi phạm SLA
          </span>
        </div>
      </div>

      <AlertsStatsCards stats={stats} loading={statsLoading} />

      <AlertsFilters filters={filters} onFiltersChange={handleFiltersChange} />

      {error && (
        <div className="sla-alerts-page__error">
          <span className="sla-alerts-page__error-icon">❌</span>
          <span className="sla-alerts-page__error-text">{error}</span>
        </div>
      )}

      {loading ? (
        <div className="sla-alerts-page__loading">
          <div className="sla-alerts-page__spinner"></div>
          <p>Đang tải cảnh báo SLA...</p>
        </div>
      ) : items.length === 0 ? (
        <div className="sla-alerts-page__empty">
          <div className="sla-alerts-page__empty-icon">✅</div>
          <h3 className="sla-alerts-page__empty-title">Không có cảnh báo SLA</h3>
          <p className="sla-alerts-page__empty-text">
            Hiện tại không có cảnh báo nào cần xử lý. Tất cả công việc đang trong SLA.
          </p>
        </div>
      ) : (
        <div className="sla-alerts-page__list">
          {items.map((alert) => (
            <AlertCard
              key={alert.id}
              alert={alert}
              onEscalate={handleEscalate}
              onReassign={handleReassign}
            />
          ))}
        </div>
      )}

      <EscalateModal
        alert={selectedAlert}
        isOpen={isEscalateModalOpen}
        onClose={() => {
          setIsEscalateModalOpen(false);
          setSelectedAlert(null);
        }}
        onConfirm={handleEscalateConfirm}
        loading={actionLoading}
      />

      <ReassignModal
        alert={selectedAlert}
        isOpen={isReassignModalOpen}
        onClose={() => {
          setIsReassignModalOpen(false);
          setSelectedAlert(null);
        }}
        onConfirm={handleReassignConfirm}
        candidates={candidates}
        loading={actionLoading}
        candidatesLoading={candidatesLoading}
      />
    </div>
  );
};
