import React, { useState } from 'react';
import { UUID } from '../../../../../models/common';
import { Button } from '../../../../../components/common/Button';
import styles from './CommentsTab.module.css';

interface CommentsTabProps {
  ticketId: UUID;
}

interface Comment {
  id: string;
  userId: string;
  userName: string;
  userAvatar: string;
  content: string;
  timestamp: Date;
}

const CommentsTab: React.FC<CommentsTabProps> = () => {
  const [comment, setComment] = useState('');
  
  // Mock comments
  const comments: Comment[] = [
    {
      id: '1',
      userId: '1',
      userName: 'Linh Dinh',
      userAvatar: 'JD',
      content: 'Đây là ticket ưu tiên cao, cần xử lý ngay.',
      timestamp: new Date('2024-03-24T08:15:00'),
    },
    {
      id: '2',
      userId: '2',
      userName: 'Nguyễn Văn A',
      userAvatar: 'NS',
      content: 'Đã liên hệ với phòng cấp cứu, họ xác nhận máy in không hoạt động.',
      timestamp: new Date('2024-03-24T09:30:00'),
    },
  ];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!comment.trim()) return;

    // TODO: Post comment via API
    console.log('Posting comment:', comment);
    setComment('');
  };

  const formatTimeAgo = (date: Date) => {
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    
    if (diffHours < 1) {
      const diffMins = Math.floor(diffMs / (1000 * 60));
      return `${diffMins} phút trước`;
    }
    if (diffHours < 24) {
      return `${diffHours} giờ trước`;
    }
    const diffDays = Math.floor(diffHours / 24);
    return `${diffDays} ngày trước`;
  };

  const getAvatarColor = (index: number) => {
    const colors = ['var(--blue-500)', 'var(--green-500)', 'var(--purple-500)', 'var(--orange-500)'];
    return colors[index % colors.length];
  };

  return (
    <div className={styles.container}>
      <div className={styles.comments}>
        {comments.length === 0 ? (
          <div className={styles.empty}>
            <i className="fas fa-comments"></i>
            <p>Chưa có comment nào</p>
          </div>
        ) : (
          comments.map((cmt, index) => (
            <div key={cmt.id} className={styles.comment}>
              <div className={styles.commentHeader}>
                <div 
                  className={styles.avatar}
                  style={{ backgroundColor: getAvatarColor(index) }}
                >
                  {cmt.userAvatar}
                </div>
                <span className={styles.userName}>{cmt.userName}</span>
                <span className={styles.timestamp}>{formatTimeAgo(cmt.timestamp)}</span>
              </div>
              <p className={styles.content}>{cmt.content}</p>
              <div className={styles.actions}>
                <button className={styles.actionBtn}>Trả lời</button>
                <button className={styles.actionBtn}>Chỉnh sửa</button>
              </div>
            </div>
          ))
        )}
      </div>
      <div className={styles.footer}>
        <form onSubmit={handleSubmit} className={styles.form}>
          <textarea
            className={styles.textarea}
            rows={3}
            placeholder="Viết comment..."
            value={comment}
            onChange={(e) => setComment(e.target.value)}
          />
          <div className={styles.formActions}>
            <Button type="submit" disabled={!comment.trim()}>
              <i className="fas fa-comment"></i> Thêm Comment
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CommentsTab;
