/**
 * ReportFilters Component
 * Quick filter controls for report parameters
 */

import React from 'react';
import { ReportPeriod, type ReportFilters as ReportFiltersType } from '../../../models/Report';
import styles from './ReportFilters.module.css';

interface ReportFiltersProps {
  filters: ReportFiltersType;
  onFiltersChange: (filters: ReportFiltersType) => void;
}

export const ReportFilters: React.FC<ReportFiltersProps> = ({
  filters,
  onFiltersChange,
}) => {
  const handlePeriodChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFiltersChange({
      ...filters,
      period: e.target.value as ReportPeriod,
    });
  };

  const handleDepartmentChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFiltersChange({
      ...filters,
      department: e.target.value,
    });
  };

  const handleTeamChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFiltersChange({
      ...filters,
      team: e.target.value,
    });
  };

  return (
    <div className={styles.filterCard}>
      <div className={styles.filterGrid}>
        <div className={styles.filterItem}>
          <label className={styles.label}>Khoảng thời gian</label>
          <select
            className={styles.select}
            value={filters.period}
            onChange={handlePeriodChange}
          >
            <option value={ReportPeriod.Last7Days}>7 ngày qua</option>
            <option value={ReportPeriod.Last30Days}>30 ngày qua</option>
            <option value={ReportPeriod.ThisMonth}>Tháng này</option>
            <option value={ReportPeriod.ThisQuarter}>Quý này</option>
            <option value={ReportPeriod.ThisYear}>Năm này</option>
            <option value={ReportPeriod.Custom}>Tùy chỉnh</option>
          </select>
        </div>

        <div className={styles.filterItem}>
          <label className={styles.label}>Phòng ban</label>
          <select
            className={styles.select}
            value={filters.department || ''}
            onChange={handleDepartmentChange}
          >
            <option value="">Tất cả</option>
            <option value="emergency">Cấp cứu</option>
            <option value="surgery">Ngoại khoa</option>
            <option value="internal">Nội khoa</option>
            <option value="it">Hỗ trợ IT</option>
          </select>
        </div>

        <div className={styles.filterItem}>
          <label className={styles.label}>Team</label>
          <select
            className={styles.select}
            value={filters.team || ''}
            onChange={handleTeamChange}
          >
            <option value="">Tất cả teams</option>
            <option value="team-a">Team A</option>
            <option value="team-b">Team B</option>
            <option value="team-c">Team C</option>
          </select>
        </div>

        <div className={styles.filterAction}>
          <button className={styles.applyButton}>
            <i className="fas fa-filter"></i> Áp dụng
          </button>
        </div>
      </div>
    </div>
  );
};
