import { apiClient } from './api';
import {
  Approval,
  ApprovalFilters,
  ApprovalStats,
  ApproveApprovalRequest,
  RejectApprovalRequest,
  RequestChangesRequest,
  DelegateApprovalRequest,
  BulkApprovalRequest,
} from '../models/Approval';
import { PaginatedResponse, UUID } from '../models/common';
import { getMockApprovals, getMockApprovalById, getMockApprovalStats } from '../mocks';

// Flag to use mock data during development
import { USE_MOCK_DATA } from '../config/appSettings';

export const approvalService = {
  /**
   * Get paginated list of approvals with optional filters
   */
  async getApprovals(
    filters?: ApprovalFilters,
    page = 1,
    pageSize = 20
  ): Promise<PaginatedResponse<Approval>> {
    // Use mock data during development
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          let filteredApprovals = getMockApprovals();

          // Apply filters
          if (filters?.status && filters.status !== 'all') {
            filteredApprovals = filteredApprovals.filter((a) => a.status === filters.status);
          }
          if (filters?.type && filters.type !== 'all') {
            filteredApprovals = filteredApprovals.filter((a) => a.type === filters.type);
          }
          if (filters?.priority && filters.priority !== 'all') {
            filteredApprovals = filteredApprovals.filter((a) => a.priority === filters.priority);
          }
          if (filters?.requesterId) {
            filteredApprovals = filteredApprovals.filter((a) => a.requesterId === filters.requesterId);
          }
          if (filters?.searchQuery) {
            const searchLower = filters.searchQuery.toLowerCase();
            filteredApprovals = filteredApprovals.filter(
              (a) =>
                a.title.toLowerCase().includes(searchLower) ||
                a.description.toLowerCase().includes(searchLower) ||
                a.requesterName.toLowerCase().includes(searchLower)
            );
          }

          // Sort by requestedAt desc
          filteredApprovals.sort(
            (a, b) => new Date(b.requestedAt).getTime() - new Date(a.requestedAt).getTime()
          );

          // Apply pagination
          const start = (page - 1) * pageSize;
          const end = start + pageSize;
          const paginatedApprovals = filteredApprovals.slice(start, end);

          resolve({
            items: paginatedApprovals,
            total: filteredApprovals.length,
            page,
            pageSize,
            totalPages: Math.ceil(filteredApprovals.length / pageSize),
          });
        }, 500); // Simulate network delay
      });
    }

    // Production: Use real API
    const queryParams = new URLSearchParams({
      page: page.toString(),
      pageSize: pageSize.toString(),
      ...(filters?.status && { status: filters.status }),
      ...(filters?.type && { type: filters.type }),
      ...(filters?.priority && { priority: filters.priority }),
      ...(filters?.requesterId && { requesterId: filters.requesterId }),
      ...(filters?.dateFrom && { dateFrom: filters.dateFrom }),
      ...(filters?.dateTo && { dateTo: filters.dateTo }),
      ...(filters?.searchQuery && { search: filters.searchQuery }),
    });

    return apiClient.get(`/api/approvals?${queryParams}`);
  },

  /**
   * Get pending approvals
   */
  async getPendingApprovals(): Promise<Approval[]> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          const approvals = getMockApprovals();
          resolve(approvals.filter((a) => a.status === 'pending'));
        }, 500);
      });
    }

    return apiClient.get('/api/approvals/pending');
  },

  /**
   * Get approval statistics
   */
  async getApprovalStats(): Promise<ApprovalStats> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve(getMockApprovalStats());
        }, 300);
      });
    }

    return apiClient.get('/api/approvals/stats');
  },

  /**
   * Get approval by ID
   */
  async getApprovalById(id: UUID): Promise<Approval> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          const approval = getMockApprovalById(id);
          if (approval) {
            resolve(approval);
          } else {
            reject(new Error('Approval not found'));
          }
        }, 300);
      });
    }

    return apiClient.get(`/api/approvals/${id}`);
  },

  /**
   * Approve an approval request
   */
  async approveApproval(request: ApproveApprovalRequest): Promise<Approval> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          const approval = getMockApprovalById(request.approvalId);
          if (approval) {
            resolve({
              ...approval,
              status: 'approved' as any,
              decidedAt: new Date().toISOString(),
              decisionNote: request.note,
            });
          }
        }, 800);
      });
    }

    return apiClient.post(`/api/approvals/${request.approvalId}/approve`, {
      note: request.note,
    });
  },

  /**
   * Reject an approval request
   */
  async rejectApproval(request: RejectApprovalRequest): Promise<Approval> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          const approval = getMockApprovalById(request.approvalId);
          if (approval) {
            resolve({
              ...approval,
              status: 'rejected' as any,
              decidedAt: new Date().toISOString(),
              decisionNote: request.reason,
            });
          }
        }, 800);
      });
    }

    return apiClient.post(`/api/approvals/${request.approvalId}/reject`, {
      reason: request.reason,
    });
  },

  /**
   * Request changes to an approval
   */
  async requestChanges(request: RequestChangesRequest): Promise<Approval> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          const approval = getMockApprovalById(request.approvalId);
          if (approval) {
            resolve({
              ...approval,
              status: 'changes_requested' as any,
              decidedAt: new Date().toISOString(),
              decisionNote: request.changes,
            });
          }
        }, 800);
      });
    }

    return apiClient.post(`/api/approvals/${request.approvalId}/request-changes`, {
      changes: request.changes,
    });
  },

  /**
   * Delegate an approval to another user
   */
  async delegateApproval(request: DelegateApprovalRequest): Promise<Approval> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          const approval = getMockApprovalById(request.approvalId);
          if (approval) {
            resolve({
              ...approval,
              status: 'delegated' as any,
              delegation: {
                delegatedTo: request.delegateToId,
                delegatedToName: request.delegateToName,
                reason: request.reason,
                timeframe: request.timeframe,
                delegatedAt: new Date().toISOString(),
              },
            });
          }
        }, 800);
      });
    }

    return apiClient.post(`/api/approvals/${request.approvalId}/delegate`, {
      delegateToId: request.delegateToId,
      delegateToName: request.delegateToName,
      reason: request.reason,
      timeframe: request.timeframe,
    });
  },

  /**
   * Bulk approve or reject multiple approvals
   */
  async bulkAction(request: BulkApprovalRequest): Promise<{ success: boolean; processed: number }> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve({
            success: true,
            processed: request.approvalIds.length,
          });
        }, 1000);
      });
    }

    return apiClient.post('/api/approvals/bulk', {
      approvalIds: request.approvalIds,
      action: request.action,
      note: request.note,
      reason: request.reason,
    });
  },
};
