import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { Line } from 'react-chartjs-2';
import { TrendDataPoint } from '../../../models/Statistics';
import { Card } from '../../common/Card';
import styles from './TrendsChart.module.css';

// Register ChartJS components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

interface TrendsChartProps {
  data: TrendDataPoint[];
}

export const TrendsChart: React.FC<TrendsChartProps> = ({ data }) => {
  const chartData = {
    labels: data.map((point) => point.label),
    datasets: [
      {
        label: 'Hoàn thành',
        data: data.map((point) => point.completed),
        borderColor: 'rgb(59, 130, 246)',
        backgroundColor: 'rgba(59, 130, 246, 0.1)',
        tension: 0.4,
        fill: true,
      },
      {
        label: 'Vi phạm SLA',
        data: data.map((point) => point.slaViolations),
        borderColor: 'rgb(239, 68, 68)',
        backgroundColor: 'rgba(239, 68, 68, 0.1)',
        tension: 0.4,
        fill: true,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: true,
    plugins: {
      legend: {
        position: 'bottom' as const,
      },
      tooltip: {
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        padding: 12,
        titleFont: {
          size: 14,
        },
        bodyFont: {
          size: 13,
        },
      },
    },
    scales: {
      y: {
        beginAtZero: true,
        ticks: {
          precision: 0,
        },
      },
    },
  };

  return (
    <Card className={styles.chartCard}>
      <h3 className={styles.title}>
        <i className="fas fa-chart-line" style={{ color: 'var(--primary-color)' }}></i>
        Xu hướng hoàn thành công việc
      </h3>
      <div className={styles.chartContainer}>
        <Line data={chartData} options={options} />
      </div>
    </Card>
  );
};
