import { UUID, Timestamps } from './common';

export interface Collaborator {
  id: UUID;
  userId: UUID;
  userName: string;
  userAvatar?: string;
  role: 'support' | 'reviewer' | 'contributor';
  effortPercentage: number; // % of total effort
  assignedAt: string;
  assignedBy: UUID;
  status: 'active' | 'completed' | 'removed';
}

export interface SupportRequest {
  description: string;
  requestedAt: string;
  requestedBy: UUID;
  suggestedCollaborators?: UUID[];
  effortPercentage?: number;
  reason: string;
}

export interface ReassignmentRequest {
  reason: string;
  requestedAt: string;
  requestedBy: UUID;
  requestedByName: string;
  suggestedAssigneeId?: UUID;
  suggestedAssigneeName?: string;
  status: 'pending' | 'approved' | 'rejected';
  reviewedAt?: string;
  reviewedBy?: UUID;
  reviewerName?: string;
  reviewNote?: string;
}

export interface BlockerInfo {
  reason: string;
  blockedBy?: UUID[]; // Task IDs that are blocking this task
  blockedAt: string;
  blockedByUserId: UUID;
  blockedByUserName: string;
}

export interface ChangesRequest {
  changes: string;
  requestedAt: string;
  requestedBy: UUID;
  requestedByName: string;
}

export interface Task extends Timestamps {
  id: UUID;
  ticketId: UUID;
  ticketNumber?: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  progress: number; // 0-100
  assignmentStrategy: AssignmentStrategy;
  assigneeId: UUID | null;
  assigneeName: string | null;
  assignToDepartmentId?: UUID; // For department assignment strategy
  assignToDepartmentName?: string; // For department assignment strategy
  creatorId: UUID;
  creatorName: string;
  estimatedHours: number;
  actualHours: number;
  dueDate: Date;
  skillsRequired: string[];
  subtasks: Subtask[];
  category?: string;
  departmentId?: UUID;
  departmentName?: string;
  tags?: string[];
  slaRemaining?: number; // Time remaining in minutes
  completedSubtasks: number;
  totalSubtasks: number;
  
  // Collaboration fields
  collaborators?: Collaborator[];
  supportRequest?: SupportRequest;
  supportRequestedAt?: string;
  
  // Workflow fields
  reassignmentRequest?: ReassignmentRequest;
  blocker?: BlockerInfo;
  changesRequest?: ChangesRequest;
  cancellationReason?: string;
  cancelledAt?: string;
  cancelledBy?: UUID;
  cancelledByName?: string;
}

export enum TaskStatus {
  Created = 'created',
  Assigned = 'assigned',
  InProgress = 'in_progress',
  SupportRequested = 'support_requested',
  CollabAssigned = 'collab_assigned',
  Blocked = 'blocked',
  UnderReview = 'under_review',
  ChangesRequested = 'changes_requested',
  Completed = 'completed',
  Cancelled = 'cancelled',
}

export enum TaskPriority {
  Critical = 'critical',
  High = 'high',
  Medium = 'medium',
  Low = 'low',
}

export enum AssignmentStrategy {
  Direct = 'direct',
  Pool = 'pool',
  Team = 'team',
}

export interface Subtask {
  id: UUID;
  title: string;
  completed: boolean;
}

export interface TaskFilters {
  status?: TaskStatus;
  priority?: TaskPriority;
  assignmentStrategy?: AssignmentStrategy;
  assigneeId?: UUID;
  skillsRequired?: string[];
  search?: string;
  category?: string;
}
