// Helper function to calculate SLA info
const calculateSLA = (hoursRemaining: number) => {
  const now = new Date();
  const targetDate = new Date(now.getTime() + hoursRemaining * 60 * 60 * 1000);
  const remainingMinutes = hoursRemaining * 60;
  const percentage = Math.min(100, Math.max(0, (remainingMinutes / (24 * 60)) * 100));
  
  let status: SLAStatus;
  let breached = false;
  
  if (remainingMinutes < 0) {
    status = SLAStatus.Breached;
    breached = true;
  } else if (percentage < 10) {
    status = SLAStatus.Danger;
  } else if (percentage < 25) {
    status = SLAStatus.Warning;
  } else {
    status = SLAStatus.Safe;
  }
  
  return {
    targetDate,
    remainingMinutes: Math.max(0, remainingMinutes),
    percentage,
    status,
    breached,
  };
};

const hoursAgo = (hours: number): Date => {
  return new Date(Date.now() - hours * 60 * 60 * 1000);
};

const hoursFromNow = (hours: number): Date => {
  return new Date(Date.now() + hours * 60 * 60 * 1000);
};

