/**
 * Get mock tickets with optional filtering
 */
export const getMockTickets = (filters?: {
  priority?: TicketPriority;
  status?: TicketStatus;
  search?: string;
  page?: number;
  pageSize?: number;
}): { items: Ticket[]; total: number; page: number; pageSize: number; totalPages: number } => {
  let filtered = [...mockTickets];
  
  if (filters?.priority) {
    filtered = filtered.filter((t) => t.priority === filters.priority);
  }
  
  if (filters?.status) {
    filtered = filtered.filter((t) => t.status === filters.status);
  }
  
  if (filters?.search) {
    const search = filters.search.toLowerCase();
    filtered = filtered.filter(
      (t) =>
        t.id.toLowerCase().includes(search) ||
        t.title.toLowerCase().includes(search) ||
        t.description.toLowerCase().includes(search) ||
        (t.ticketNumber && t.ticketNumber.toLowerCase().includes(search))
    );
  }
  
  const total = filtered.length;
  const page = filters?.page || 1;
  const pageSize = filters?.pageSize || 20;
  const totalPages = Math.ceil(total / pageSize);
  const start = (page - 1) * pageSize;
  const end = start + pageSize;
  
  return {
    items: filtered.slice(start, end),
    total,
    page,
    pageSize,
    totalPages,
  };
};

/**
 * Get mock ticket by ID
 */
export const getMockTicketById = (id: string): Ticket | undefined => {
  return mockTickets.find((t) => t.id === id);
};

/**
 * Mock ticket stats
 */
export const getMockTicketStats = () => {
  return {
    total: mockTickets.length,
    submitted: mockTickets.filter((t) => t.status === TicketStatus.Submitted).length,
    pending: mockTickets.filter((t) => t.status === TicketStatus.Pending).length,
    triaged: mockTickets.filter((t) => t.status === TicketStatus.Triaged).length,
    assigned: mockTickets.filter((t) => t.status === TicketStatus.Assigned).length,
    inProgress: mockTickets.filter((t) => t.status === TicketStatus.InProgress).length,
    helpRequested: mockTickets.filter((t) => t.status === TicketStatus.HelpRequested).length,
    supportAssigned: mockTickets.filter((t) => t.status === TicketStatus.SupportAssigned).length,
    blocked: mockTickets.filter((t) => t.status === TicketStatus.Blocked).length,
    resolved: mockTickets.filter((t) => t.status === TicketStatus.Resolved).length,
    approved: mockTickets.filter((t) => t.status === TicketStatus.Approved).length,
    reopened: mockTickets.filter((t) => t.status === TicketStatus.Reopened).length,
    closed: mockTickets.filter((t) => t.status === TicketStatus.Closed).length,
    rejected: mockTickets.filter((t) => t.status === TicketStatus.Rejected).length,
  };
};
