import React from 'react';
import { SLAAlert } from '../../../models/SLAAlert';
import { Badge } from '../../common/Badge';
import { Button } from '../../common/Button';
import { CountdownTimer } from '../CountdownTimer';
import { formatDistanceToNow } from 'date-fns';
import { vi } from 'date-fns/locale';
import './AlertCard.css';

interface AlertCardProps {
  alert: SLAAlert;
  onEscalate: (alert: SLAAlert) => void;
  onReassign: (alert: SLAAlert) => void;
}

export const AlertCard: React.FC<AlertCardProps> = ({ alert, onEscalate, onReassign }) => {
  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'breached':
        return 'danger';
      case 'danger':
        return 'warning';
      case 'warning':
        return 'info';
      case 'watch':
        return 'secondary';
      default:
        return 'secondary';
    }
  };

  const getSeverityLabel = (severity: string) => {
    switch (severity) {
      case 'breached':
        return 'Vi phạm SLA';
      case 'danger':
        return 'Nguy cơ cao';
      case 'warning':
        return 'Cảnh báo';
      case 'watch':
        return 'Theo dõi';
      default:
        return severity;
    }
  };

  const getTypeLabel = (type: string) => {
    switch (type) {
      case 'ticket':
        return 'Phiếu yêu cầu';
      case 'task':
        return 'Công việc';
      default:
        return type;
    }
  };

  return (
    <div className={`alert-card alert-card--${alert.severity}`}>
      <div className="alert-card__header">
        <div className="alert-card__title-row">
          <h3 className="alert-card__title">{alert.title}</h3>
          <Badge variant={getSeverityColor(alert.severity)}>
            {getSeverityLabel(alert.severity)}
          </Badge>
        </div>
        <div className="alert-card__meta">
          <span className="alert-card__id">{alert.relatedId}</span>
          <span className="alert-card__separator">•</span>
          <span className="alert-card__type">{getTypeLabel(alert.type)}</span>
          {alert.departmentName && (
            <>
              <span className="alert-card__separator">•</span>
              <span className="alert-card__department">{alert.departmentName}</span>
            </>
          )}
        </div>
      </div>

      <div className="alert-card__body">
        <div className="alert-card__info-row">
          <div className="alert-card__info-item">
            <span className="alert-card__label">Người phụ trách:</span>
            <span className="alert-card__value">{alert.assigneeName}</span>
          </div>
          <div className="alert-card__info-item">
            <span className="alert-card__label">SLA còn lại:</span>
            <CountdownTimer deadline={alert.slaDeadline} />
          </div>
        </div>

        {alert.escalationLevel > 0 && (
          <div className="alert-card__escalation">
            <span className="alert-card__escalation-icon">🔥</span>
            <span className="alert-card__escalation-text">
              Đã leo thang {alert.escalationLevel} lần
            </span>
            {alert.escalatedAt && (
              <span className="alert-card__escalation-to">
                {formatDistanceToNow(new Date(alert.escalatedAt), { addSuffix: true, locale: vi })}
              </span>
            )}
          </div>
        )}

        <div className="alert-card__timestamps">
          <div className="alert-card__timestamp">
            <span className="alert-card__timestamp-label">Tạo:</span>
            <span className="alert-card__timestamp-value">
              {formatDistanceToNow(new Date(alert.createdAt), {
                addSuffix: true,
                locale: vi,
              })}
            </span>
          </div>
          <div className="alert-card__timestamp">
            <span className="alert-card__timestamp-label">Hoạt động cuối:</span>
            <span className="alert-card__timestamp-value">
              {formatDistanceToNow(new Date(alert.lastActivityAt), {
                addSuffix: true,
                locale: vi,
              })}
            </span>
          </div>
        </div>
      </div>

      <div className="alert-card__footer">
        <div className="alert-card__actions">
          <Button variant="secondary" size="sm" onClick={() => onReassign(alert)}>
            Chuyển giao
          </Button>
          <Button variant="primary" size="sm" onClick={() => onEscalate(alert)}>
            Leo thang
          </Button>
        </div>
      </div>
    </div>
  );
};
