import React, { useState } from 'react';
import { useAppDispatch } from '../../../store/hooks';
import { createTask } from '../../../store/slices/tasksSlice';
import { TaskPriority, AssignmentStrategy } from '../../../models/Task';
import { Input } from '../../../components/common/Input';
import { TextArea } from '../../../components/common/TextArea';
import { Select, SelectOption } from '../../../components/common/Select';
import { Button } from '../../../components/common/Button';
import styles from './CreateTaskForm.module.css';

interface CreateTaskFormProps {
  onSuccess: () => void;
}

export const CreateTaskForm: React.FC<CreateTaskFormProps> = ({ onSuccess }) => {
  const dispatch = useAppDispatch();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    priority: TaskPriority.Medium,
    estimatedHours: 0,
    dueDate: '',
    category: '',
    departmentId: '',
    departmentName: '',
    assignmentStrategy: AssignmentStrategy.Pool,
    assigneeId: '',
    assigneeName: '',
    assignToDepartmentId: '',
    assignToDepartmentName: '',
    tags: '',
    skillsRequired: '',
  });

  const priorityOptions: SelectOption[] = [
    { value: TaskPriority.Low, label: 'Thấp' },
    { value: TaskPriority.Medium, label: 'Trung bình' },
    { value: TaskPriority.High, label: 'Cao' },
    { value: TaskPriority.Critical, label: 'Khẩn cấp' },
  ];

  const departmentOptions: SelectOption[] = [
    { value: '', label: 'Chọn phòng ban...' },
    { value: 'dept-it', label: 'Phòng IT' },
    { value: 'dept-hr', label: 'Phòng Hành Chính' },
    { value: 'dept-emergency', label: 'Cấp Cứu' },
    { value: 'dept-clinical', label: 'Phòng Khám' },
    { value: 'dept-admin', label: 'Hành Chính' },
  ];

  const assignmentStrategyOptions: SelectOption[] = [
    { value: AssignmentStrategy.Direct, label: 'Chỉ định người' },
    { value: AssignmentStrategy.Team, label: 'Chỉ định phòng ban' },
    { value: AssignmentStrategy.Pool, label: 'Đưa vào danh mục chờ nhận' },
  ];

  const staffOptions: SelectOption[] = [
    { value: '', label: 'Chọn người thực hiện...' },
    { value: 'user-001', label: 'Đinh Bộ Lĩnh' },
    { value: 'user-002', label: 'Trần Quản Lý' },
    { value: 'user-003', label: 'Nguyễn Văn A' },
    { value: 'user-004', label: 'Lê Thị B' },
    { value: 'user-005', label: 'Phạm Văn C' },
  ];

  const assignToDepartmentOptions: SelectOption[] = [
    { value: '', label: 'Chọn phòng ban...' },
    { value: 'dept-it', label: 'Phòng IT' },
    { value: 'dept-hr', label: 'Phòng Hành Chính' },
    { value: 'dept-emergency', label: 'Cấp Cứu' },
    { value: 'dept-clinical', label: 'Phòng Khám' },
    { value: 'dept-admin', label: 'Hành Chính' },
  ];

  const handleChange = (
    field: string,
    value: string | number | TaskPriority | AssignmentStrategy
  ) => {
    setFormData((prev) => {
      // If changing department, update both departmentId and departmentName
      if (field === 'departmentId') {
        const selectedDept = departmentOptions.find(d => d.value === value);
        return {
          ...prev,
          departmentId: value as string,
          departmentName: selectedDept?.label || '',
        };
      }
      // If changing assignee, update both assigneeId and assigneeName
      if (field === 'assigneeId') {
        const selectedStaff = staffOptions.find(s => s.value === value);
        return {
          ...prev,
          assigneeId: value as string,
          assigneeName: selectedStaff?.label || '',
        };
      }
      // If changing assign to department, update both ID and Name
      if (field === 'assignToDepartmentId') {
        const selectedDept = assignToDepartmentOptions.find(d => d.value === value);
        return {
          ...prev,
          assignToDepartmentId: value as string,
          assignToDepartmentName: selectedDept?.label || '',
        };
      }
      return { ...prev, [field]: value };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const taskData = {
        ...formData,
        estimatedHours: Number(formData.estimatedHours),
        dueDate: new Date(formData.dueDate),
        skillsRequired: formData.skillsRequired
          .split(',')
          .map((s) => s.trim())
          .filter((s) => s),
        tags: formData.tags
          .split(',')
          .map((t) => t.trim())
          .filter((t) => t),
      };

      await dispatch(createTask(taskData)).unwrap();
      onSuccess();
    } catch (error) {
      console.error('Failed to create task:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className={styles.form}>
      <div className={styles.formGroup}>
        <label className={styles.label}>
          Tiêu đề <span className={styles.required}>*</span>
        </label>
        <Input
          value={formData.title}
          onChange={(e) => handleChange('title', e.target.value)}
          placeholder="Nhập tiêu đề task..."
          required
        />
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>Mô tả</label>
        <TextArea
          value={formData.description}
          onChange={(e) => handleChange('description', e.target.value)}
          placeholder="Mô tả chi tiết về task..."
          rows={4}
        />
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>
          Hạn chót <span className={styles.required}>*</span>
        </label>
        <Input
          type="date"
          value={formData.dueDate}
          onChange={(e) => handleChange('dueDate', e.target.value)}
          required
        />
      </div>

      <div className={styles.formRow}>
        <div className={styles.formGroup}>
          <label className={styles.label}>
            Ưu tiên <span className={styles.required}>*</span>
          </label>
          <Select
            value={formData.priority}
            onChange={(e) => handleChange('priority', e.target.value as TaskPriority)}
            required
            options={priorityOptions}
          />
        </div>

        <div className={styles.formGroup}>
          <label className={styles.label}>Ước tính (giờ)</label>
          <Input
            type="number"
            value={formData.estimatedHours}
            onChange={(e) => handleChange('estimatedHours', e.target.value)}
            placeholder="0"
            min="0"
            step="0.5"
          />
        </div>
      </div>

      <div className={styles.formRow}>
        <div className={styles.formGroup}>
          <label className={styles.label}>Danh mục</label>
          <Input
            value={formData.category}
            onChange={(e) => handleChange('category', e.target.value)}
            placeholder="IT, Database, HR, ..."
          />
        </div>

        <div className={styles.formGroup}>
          <label className={styles.label}>Phòng ban</label>
          <Select
            value={formData.departmentId}
            onChange={(e) => handleChange('departmentId', e.target.value)}
            options={departmentOptions}
          />
        </div>
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>Tags</label>
        <Input
          value={formData.tags}
          onChange={(e) => handleChange('tags', e.target.value)}
          placeholder="urgent, database, hardware, ... (phân cách bằng dấu phẩy)"
        />
        <small className={styles.hint}>
          <i className="fas fa-tag"></i> Phân cách các tag bằng dấu phẩy
        </small>
      </div>

      <div className={styles.formGroup}>
        <label className={styles.label}>Kỹ năng yêu cầu</label>
        <Input
          value={formData.skillsRequired}
          onChange={(e) => handleChange('skillsRequired', e.target.value)}
          placeholder="SQL, Network, ... (phân cách bằng dấu phẩy)"
        />
        <small className={styles.hint}>Phân cách các kỹ năng bằng dấu phẩy</small>
      </div>

      {/* Assignment Strategy Section */}
      <div className={styles.sectionDivider}></div>

      <div className={styles.formGroup}>
        <label className={styles.label}>
          Phân công <span className={styles.required}>*</span>
        </label>
        <Select
          value={formData.assignmentStrategy}
          onChange={(e) => handleChange('assignmentStrategy', e.target.value as AssignmentStrategy)}
          required
          options={assignmentStrategyOptions}
        />
      </div>

      {/* Conditional: Direct Assignment - Show Staff Picker */}
      {formData.assignmentStrategy === AssignmentStrategy.Direct && (
        <div className={styles.formGroup}>
          <label className={styles.label}>
            Người thực hiện <span className={styles.required}>*</span>
          </label>
          <Select
            value={formData.assigneeId}
            onChange={(e) => handleChange('assigneeId', e.target.value)}
            required
            options={staffOptions}
          />
        </div>
      )}

      {/* Conditional: Team Assignment - Show Department Picker */}
      {formData.assignmentStrategy === AssignmentStrategy.Team && (
        <div className={styles.formGroup}>
          <label className={styles.label}>
            Phòng ban thực hiện <span className={styles.required}>*</span>
          </label>
          <Select
            value={formData.assignToDepartmentId}
            onChange={(e) => handleChange('assignToDepartmentId', e.target.value)}
            required
            options={assignToDepartmentOptions}
          />
        </div>
      )}

      {/* Pool Assignment - No additional field needed */}
      {formData.assignmentStrategy === AssignmentStrategy.Pool && (
        <div className={styles.infoBox}>
          <i className="fas fa-info-circle"></i>
          <span>Task sẽ được đưa vào danh mục chờ nhận. Nhân viên có thể tự chọn nhận task này.</span>
        </div>
      )}

      <div className={styles.formActions}>
        <Button type="submit" variant="primary" disabled={loading}>
          {loading ? (
            <>
              <i className="fas fa-spinner fa-spin"></i> Đang tạo...
            </>
          ) : (
            <>
              <i className="fas fa-plus"></i> Tạo Task
            </>
          )}
        </Button>
      </div>
    </form>
  );
};
