import { apiClient } from './api';
import {
  SLAAlert,
  SLAAlertFilters,
  SLAStats,
  EscalateRequest,
  ReassignAlertRequest,
  CandidateSuggestion,
} from '../models/SLAAlert';
import { PaginatedResponse, UUID } from '../models/common';
import {
  getMockSLAAlerts,
  getMockSLAStats,
  getMockSLAAlertById,
  getMockCandidateSuggestions,
} from '../mocks';

// Flag to use mock data during development
import { USE_MOCK_DATA } from '../config/appSettings';

export const slaAlertService = {
  /**
   * Get all SLA alerts with optional filters
   */
  async getSLAAlerts(
    filters?: SLAAlertFilters,
    page = 1,
    pageSize = 50
  ): Promise<PaginatedResponse<SLAAlert>> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          let filteredAlerts = getMockSLAAlerts();

          // Apply filters
          if (filters?.severity && filters.severity !== 'all') {
            filteredAlerts = filteredAlerts.filter((a) => a.severity === filters.severity);
          }
          if (filters?.type && filters.type !== 'all') {
            filteredAlerts = filteredAlerts.filter((a) => a.type === filters.type);
          }
          if (filters?.departmentId && filters.departmentId !== 'all') {
            filteredAlerts = filteredAlerts.filter((a) => a.departmentId === filters.departmentId);
          }
          if (filters?.assigneeId) {
            filteredAlerts = filteredAlerts.filter((a) => a.assigneeId === filters.assigneeId);
          }
          if (filters?.searchQuery) {
            const searchLower = filters.searchQuery.toLowerCase();
            filteredAlerts = filteredAlerts.filter(
              (a) =>
                a.title.toLowerCase().includes(searchLower) ||
                a.relatedNumber.toLowerCase().includes(searchLower) ||
                a.assigneeName.toLowerCase().includes(searchLower)
            );
          }

          // Sort by severity then time remaining
          const severityOrder = { breached: 0, danger: 1, warning: 2, watch: 3 };
          filteredAlerts.sort((a, b) => {
            const severityDiff =
              severityOrder[a.severity] - severityOrder[b.severity];
            if (severityDiff !== 0) return severityDiff;
            return a.slaMinutesRemaining - b.slaMinutesRemaining;
          });

          // Apply pagination
          const start = (page - 1) * pageSize;
          const end = start + pageSize;
          const paginatedAlerts = filteredAlerts.slice(start, end);

          resolve({
            items: paginatedAlerts,
            total: filteredAlerts.length,
            page,
            pageSize,
            totalPages: Math.ceil(filteredAlerts.length / pageSize),
          });
        }, 500);
      });
    }

    // Production: Use real API
    const queryParams = new URLSearchParams({
      page: page.toString(),
      pageSize: pageSize.toString(),
      ...(filters?.severity && { severity: filters.severity }),
      ...(filters?.type && { type: filters.type }),
      ...(filters?.departmentId && { departmentId: filters.departmentId }),
      ...(filters?.assigneeId && { assigneeId: filters.assigneeId }),
      ...(filters?.searchQuery && { search: filters.searchQuery }),
    });

    return apiClient.get(`/api/sla/alerts?${queryParams}`);
  },

  /**
   * Get SLA statistics
   */
  async getSLAStats(): Promise<SLAStats> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve(getMockSLAStats());
        }, 300);
      });
    }

    return apiClient.get('/api/sla/stats');
  },

  /**
   * Get alert by ID
   */
  async getSLAAlertById(id: UUID): Promise<SLAAlert> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          const alert = getMockSLAAlertById(id);
          if (alert) {
            resolve(alert);
          } else {
            reject(new Error('SLA Alert not found'));
          }
        }, 300);
      });
    }

    return apiClient.get(`/api/sla/alerts/${id}`);
  },

  /**
   * Escalate an SLA alert
   */
  async escalateAlert(request: EscalateRequest): Promise<SLAAlert> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          const alert = getMockSLAAlertById(request.alertId);
          if (alert) {
            resolve({
              ...alert,
              escalationLevel: (alert.escalationLevel || 0) + 1,
              escalatedAt: new Date().toISOString(),
            });
          }
        }, 800);
      });
    }

    return apiClient.post(`/api/sla/${request.alertId}/escalate`, {
      reason: request.reason,
      escalateTo: request.escalateTo,
    });
  },

  /**
   * Reassign an alert (ticket or task)
   */
  async reassignAlert(request: ReassignAlertRequest): Promise<void> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve();
        }, 800);
      });
    }

    // Call appropriate API based on type
    if (request.type === 'ticket') {
      return apiClient.post(`/api/tickets/${request.relatedId}/reassign`, {
        newAssigneeId: request.newAssigneeId,
        newAssigneeName: request.newAssigneeName,
        reason: request.reason,
      });
    } else {
      return apiClient.post(`/api/tasks/${request.relatedId}/reassign`, {
        newAssigneeId: request.newAssigneeId,
        newAssigneeName: request.newAssigneeName,
        reason: request.reason,
      });
    }
  },

  /**
   * Get candidate suggestions for reassignment
   */
  async getCandidateSuggestions(
    alertId: UUID,
    skillsRequired?: string[]
  ): Promise<CandidateSuggestion[]> {
    if (USE_MOCK_DATA) {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve(getMockCandidateSuggestions());
        }, 500);
      });
    }

    const queryParams = new URLSearchParams({
      alertId,
      ...(skillsRequired && { skills: skillsRequired.join(',') }),
    });

    return apiClient.get(`/api/users/candidates?${queryParams}`);
  },
};
