import React from 'react';
import { Card } from '../../../components/common/Card';
import styles from './TaskStatsCards.module.css';

interface TaskStatsCardsProps {
  stats: {
    total: number;
    assigned: number;
    inProgress: number;
    completed: number;
    overdue: number;
  };
}

export const TaskStatsCards: React.FC<TaskStatsCardsProps> = ({ stats }) => {
  const cards = [
    {
      title: 'Total Tasks',
      count: stats.total,
      icon: 'fa-tasks',
      color: 'primary',
    },
    {
      title: 'Đã Giao',
      count: stats.assigned,
      icon: 'fa-user-check',
      color: 'info',
    },
    {
      title: 'Đang Thực Hiện',
      count: stats.inProgress,
      icon: 'fa-spinner',
      color: 'warning',
    },
    {
      title: 'Hoàn Thành',
      count: stats.completed,
      icon: 'fa-check-circle',
      color: 'success',
    },
    {
      title: 'Quá Hạn',
      count: stats.overdue,
      icon: 'fa-exclamation-triangle',
      color: 'danger',
    },
  ];

  return (
    <div className={styles.statsGrid}>
      {cards.map((card) => (
        <Card key={card.title} className={styles.statCard}>
          <div className={styles.statContent}>
            <div className={styles.statInfo}>
              <div className={styles.statTitle}>{card.title}</div>
              <div className={styles.statCount}>{card.count}</div>
            </div>
            <div className={`${styles.statIcon} ${styles[card.color]}`}>
              <i className={`fas ${card.icon}`}></i>
            </div>
          </div>
        </Card>
      ))}
    </div>
  );
};
