import React from 'react';
import { Ticket } from '../../../../models/Ticket';
import { TicketTableRow } from './TicketTableRow';
import styles from './TicketTable.module.css';

export interface TicketTableProps {
  tickets: Ticket[];
  loading: boolean;
  onView: (ticket: Ticket) => void;
  onEdit: (ticket: Ticket) => void;
  onAssign: (ticket: Ticket) => void;
  onTriage: (ticket: Ticket) => void;
}

export const TicketTable: React.FC<TicketTableProps> = ({
  tickets,
  loading,
  onView,
  onEdit,
  onAssign,
  onTriage,
}) => {
  if (loading) {
    return (
      <div className={styles.loading}>
        <div className={styles.spinner}></div>
        <span>Đang tải dữ liệu...</span>
      </div>
    );
  }

  if (tickets.length === 0) {
    return (
      <div className={styles.empty}>
        <i className="fas fa-inbox fa-3x"></i>
        <h3>Không có phiếu yêu cầu nào</h3>
        <p>Hãy tạo phiếu yêu cầu mới để bắt đầu</p>
      </div>
    );
  }

  return (
    <div className={styles.container}>
      <div className={styles.tableWrapper}>
        <table className={styles.table}>
          <thead className={styles.thead}>
            <tr>
              <th className={styles.th}>Mã số</th>
              <th className={styles.th}>Tiêu đề</th>
              <th className={styles.th}>Phòng ban</th>
              <th className={styles.th}>Độ ưu tiên</th>
              <th className={styles.th}>SLA</th>
              <th className={styles.th}>Người xử lý</th>
              <th className={styles.th}>Trạng thái</th>
              <th className={styles.th}>Thao tác</th>
            </tr>
          </thead>
          <tbody className={styles.tbody}>
            {tickets.map((ticket) => (
              <TicketTableRow
                key={ticket.id}
                ticket={ticket}
                onView={onView}
                onEdit={onEdit}
                onAssign={onAssign}
                onTriage={onTriage}
              />
            ))}
          </tbody>
        </table>
      </div>

      {/* Mobile card view */}
      <div className={styles.mobileCards}>
        {tickets.map((ticket) => (
          <div
            key={ticket.id}
            className={styles.mobileCard}
            onClick={() => onView(ticket)}
          >
            <div className={styles.mobileCardHeader}>
              <span className={styles.mobileCode}>#{ticket.id.substring(0, 8)}</span>
              <span className={`${styles.status} ${styles[`status-${ticket.status.toLowerCase()}`]}`}>
                {ticket.status}
              </span>
            </div>
            <h4 className={styles.mobileTitle}>{ticket.title}</h4>
            <div className={styles.mobileDetails}>
              <span className={styles.mobileDetail}>
                <i className="fas fa-building"></i> {ticket.departmentName}
              </span>
              <span className={styles.mobileDetail}>
                <i className="fas fa-user"></i> {ticket.assigneeName || 'Chưa gán'}
              </span>
            </div>
            <div className={styles.mobileFooter}>
              <span className={`${styles.priority} ${styles[`priority-${ticket.priority.toLowerCase()}`]}`}>
                {ticket.priority}
              </span>
              <div className={styles.mobileActions} onClick={(e) => e.stopPropagation()}>
                {/* No actions in mobile view - tap card to view */}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
