import React from 'react';
import { Task } from '../../../../models/Task';
import { Button } from '../../../../components/common/Button';
import { getPriorityBadge, getStatusBadge } from '../../utils/badgeHelpers';
import styles from './TaskHeader.module.css';

export interface TaskHeaderProps {
  task: Task;
  onBack: () => void;
  onSubmitForReview?: () => void;
}

export const TaskHeader: React.FC<TaskHeaderProps> = ({ task, onBack, onSubmitForReview }) => {
  const showSubmitButton = task.status === 'in_progress' && task.progress >= 90;

  return (
    <>
      {/* Breadcrumb & Back Button */}
      <div className={styles.breadcrumb}>
        <Button variant="secondary" size="sm" onClick={onBack}>
          <i className="fas fa-arrow-left"></i> Quay lại danh sách
        </Button>
        <div className={styles.breadcrumbPath}>
          <span onClick={onBack} className={styles.breadcrumbLink}>
            Tasks
          </span>
          <i className="fas fa-chevron-right"></i>
          <span>{task.ticketNumber || task.id}</span>
        </div>
      </div>

      {/* Header */}
      <div className={styles.header}>
        <div className={styles.headerLeft}>
          <div className={styles.headerTitle}>
            <span className={styles.taskId}>{task.ticketNumber || task.id}</span>
            {getPriorityBadge(task.priority)}
            {getStatusBadge(task.status)}
          </div>
          <h1 className={styles.title}>{task.title}</h1>
        </div>
        {showSubmitButton && onSubmitForReview && (
          <Button variant="success" onClick={onSubmitForReview}>
            <i className="fas fa-check-circle"></i> Gửi yêu cầu xem xét
          </Button>
        )}
      </div>
    </>
  );
};
