import React, { useEffect } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { logout } from '../../../store/slices/authSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { fetchApprovalStats } from '../../../store/slices/approvalsSlice';
import { fetchSLAStats } from '../../../store/slices/slaAlertsSlice';
import { Sidebar, NavSection } from '../Sidebar';
import { Topbar } from '../Topbar';
import { ErrorBoundary } from '../ErrorBoundary';
import styles from './AppLayout.module.css';

const navSections: NavSection[] = [
  {
    title: 'Menu Chính',
    items: [
      {
        id: 'dashboard',
        label: 'Bảng điều khiển',
        icon: 'fas fa-home',
        path: '/dashboard',
      },
      {
        id: 'tickets',
        label: 'Phiếu yêu cầu',
        icon: 'fas fa-ticket-alt',
        path: '/tickets',
        badge: 5,
      },
      {
        id: 'tasks',
        label: 'Công việc của tôi',
        icon: 'fas fa-tasks',
        path: '/tasks',
        badge: 8,
      },
      {
        id: 'task-pool',
        label: 'Công việc chờ nhận',
        icon: 'fas fa-swimming-pool',
        path: '/task-pool',
      },
    ],
  },
  {
    title: 'Quản lý',
    items: [
      {
        id: 'approvals',
        label: 'Phê duyệt',
        icon: 'fas fa-check-double',
        path: '/approvals',
        badge: 0, // Will be updated dynamically
      },
      {
        id: 'sla-alerts',
        label: 'Cảnh báo SLA',
        icon: 'fas fa-exclamation-triangle',
        path: '/sla-alerts',
        badge: 0, // Will be updated dynamically
      },
      {
        id: 'reports',
        label: 'Báo cáo',
        icon: 'fas fa-chart-bar',
        path: '/reports',
      },
    ],
  },
  {
    title: 'Công việc',
    items: [
      {
        id: 'history',
        label: 'Lịch sử',
        icon: 'fas fa-clock',
        path: '/history',
      },
      {
        id: 'statistics',
        label: 'Thống kê',
        icon: 'fas fa-chart-line',
        path: '/statistics',
      },
    ],
  },
  {
    title: 'Khác',
    items: [
      {
        id: 'settings',
        label: 'Cài đặt',
        icon: 'fas fa-cog',
        path: '/settings',
      },
      {
        id: 'help',
        label: 'Trợ giúp',
        icon: 'fas fa-question-circle',
        path: '/help',
      },
    ],
  },
];

export const AppLayout: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const dispatch = useAppDispatch();
  const currentUser = useAppSelector((state) => state.auth.user);
  const approvalStats = useAppSelector((state) => state.approvals.stats);
  const slaStats = useAppSelector((state) => state.slaAlerts.stats);

  // Fetch approval stats and SLA stats on mount
  useEffect(() => {
    dispatch(fetchApprovalStats());
    dispatch(fetchSLAStats());
  }, [dispatch]);

  // Update nav sections with dynamic badge counts
  const updatedNavSections = navSections.map((section) => {
    if (section.title === 'Quản lý') {
      return {
        ...section,
        items: section.items.map((item) => {
          if (item.id === 'approvals') {
            return {
              ...item,
              badge: approvalStats?.pending || 0,
            };
          }
          if (item.id === 'sla-alerts') {
            const totalAlerts = (slaStats?.breached || 0) + (slaStats?.danger || 0);
            return {
              ...item,
              badge: totalAlerts,
            };
          }
          return item;
        }),
      };
    }
    return section;
  });

  const handleNavigate = (path: string) => {
    navigate(path);
  };

  const handleLogout = async () => {
    try {
      await dispatch(logout()).unwrap();
      dispatch(addToast({
        message: 'Đăng xuất thành công',
        type: 'success',
      }));
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      // Still navigate to login even if logout fails
      navigate('/login');
    }
  };

  const handleNotificationClick = () => {
    console.log('Notification clicked');
  };

  const getPageTitle = () => {
    const path = location.pathname;
    if (path === '/dashboard') return 'Bảng điều khiển';
    if (path === '/tickets') return 'Phiếu yêu cầu';
    if (path === '/tasks') return 'Công việc của tôi';
    if (path === '/task-pool') return 'Công việc chờ nhận';
    if (path === '/approvals') return 'Phê duyệt';
    if (path === '/sla-alerts') return 'Cảnh báo SLA';
    if (path === '/reports') return 'Báo cáo & Phân tích';
    return 'QLCV Y Khoa';
  };

  // Helper to get user role label in Vietnamese
  const getUserRoleLabel = (role?: string) => {
    switch (role) {
      case 'admin':
        return 'Quản trị viên';
      case 'manager':
        return 'Quản lý';
      case 'staff':
        return 'Nhân viên';
      default:
        return 'Người dùng';
    }
  };

  // Helper to get user initials
  const getUserInitials = (fullName?: string) => {
    if (!fullName) return 'NN';
    const parts = fullName.split(' ');
    if (parts.length >= 2) {
      return (parts[parts.length - 2].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
    }
    return fullName.charAt(0).toUpperCase();
  };

  return (
    <div className={styles.layout}>
      <Sidebar
        sections={updatedNavSections}
        activePath={location.pathname}
        userName={currentUser?.fullName || 'Người dùng'}
        userRole={getUserRoleLabel(currentUser?.role)}
        userInitials={getUserInitials(currentUser?.fullName)}
        onNavigate={handleNavigate}
        onLogout={handleLogout}
      />
      <div className={styles.main}>
        <Topbar
          title={getPageTitle()}
          onSearch={(query) => console.log('Search:', query)}
          notificationCount={5}
          onNotificationClick={handleNotificationClick}
        />
        <div className={styles.content}>
          <ErrorBoundary>
            <Outlet />
          </ErrorBoundary>
        </div>
      </div>
    </div>
  );
};

export default AppLayout;
