import React, { useState } from 'react';
import { Button } from '../../../components/common/Button';
import { Modal } from '../../../components/common/Modal/Modal';
import { Ticket, TicketHelper } from '../../../models/Ticket';
import { UUID } from '../../../models/common';
import styles from './SupportAssignmentModal.module.css';

interface SupportAssignmentModalProps {
  ticket: Ticket;
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (helpers: Omit<TicketHelper, 'id' | 'assignedAt' | 'assignedById' | 'assignedByName'>[]) => Promise<void>;
}

interface StaffMember {
  id: UUID;
  name: string;
  avatar: string;
  department: string;
  skills: string[];
  currentTickets: number;
  availability: 'available' | 'busy' | 'unavailable';
}

const SupportAssignmentModal: React.FC<SupportAssignmentModalProps> = ({
  ticket,
  isOpen,
  onClose,
  onSubmit,
}) => {
  const [selectedHelpers, setSelectedHelpers] = useState<UUID[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Mock staff data - same department as ticket for realism
  const availableStaff: StaffMember[] = [
    {
      id: 'user-002',
      name: 'Trần Văn B',
      avatar: 'TB',
      department: ticket.departmentName,
      skills: ['Database', 'SQL', 'Performance Tuning'],
      currentTickets: 3,
      availability: 'available',
    },
    {
      id: 'user-003',
      name: 'Nguyễn Thị C',
      avatar: 'NC',
      department: ticket.departmentName,
      skills: ['Hardware', 'IT Support', 'Troubleshooting'],
      currentTickets: 2,
      availability: 'available',
    },
    {
      id: 'user-004',
      name: 'Lê Văn D',
      avatar: 'LD',
      department: ticket.departmentName,
      skills: ['Networking', 'System Admin', 'Security'],
      currentTickets: 5,
      availability: 'busy',
    },
    {
      id: 'user-005',
      name: 'Phạm Thị E',
      avatar: 'PE',
      department: ticket.departmentName,
      skills: ['Frontend', 'UI/UX', 'Testing'],
      currentTickets: 4,
      availability: 'available',
    },
    {
      id: 'user-006',
      name: 'Hoàng Văn F',
      avatar: 'HF',
      department: ticket.departmentName,
      skills: ['Backend', 'API', 'Database'],
      currentTickets: 1,
      availability: 'available',
    },
  ];

  const toggleHelper = (userId: UUID) => {
    setSelectedHelpers((prev) =>
      prev.includes(userId) ? prev.filter((id) => id !== userId) : [...prev, userId]
    );
    setError(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (selectedHelpers.length === 0) {
      setError('Vui lòng chọn ít nhất 1 người hỗ trợ');
      return;
    }

    setSubmitting(true);
    setError(null);

    try {
      const helpers = selectedHelpers.map((userId) => {
        const staff = availableStaff.find((s) => s.id === userId);
        return {
          userId,
          userName: staff?.name || '',
        };
      });

      await onSubmit(helpers);
      handleClose();
    } catch (err) {
      setError('Có lỗi xảy ra khi phân công người hỗ trợ. Vui lòng thử lại.');
      console.error('Error assigning support:', err);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    if (!submitting) {
      setSelectedHelpers([]);
      setError(null);
      onClose();
    }
  };

  const getAvailabilityBadge = (availability: StaffMember['availability']) => {
    const badges = {
      available: { text: 'Sẵn sàng', className: styles.badgeAvailable },
      busy: { text: 'Bận', className: styles.badgeBusy },
      unavailable: { text: 'Không khả dụng', className: styles.badgeUnavailable },
    };
    const badge = badges[availability];
    return <span className={`${styles.availabilityBadge} ${badge.className}`}>{badge.text}</span>;
  };

  if (!isOpen) return null;

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Phân Công Người Hỗ Trợ" size="lg">
      <form onSubmit={handleSubmit} className={styles.form}>
        {/* Ticket Info */}
        <div className={styles.ticketInfo}>
          <div className={styles.infoHeader}>
            <i className="fas fa-ticket-alt"></i>
            <h4>Thông Tin Ticket</h4>
          </div>
          <div className={styles.infoGrid}>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Mã Ticket:</span>
              <span className={styles.infoValue}>{ticket.ticketNumber || ticket.id}</span>
            </div>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Tiêu đề:</span>
              <span className={styles.infoValue}>{ticket.title}</span>
            </div>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Người xử lý chính:</span>
              <span className={styles.infoValue}>{ticket.assigneeName || 'Chưa giao'}</span>
            </div>
            <div className={styles.infoItem}>
              <span className={styles.infoLabel}>Phòng ban:</span>
              <span className={styles.infoValue}>{ticket.departmentName}</span>
            </div>
          </div>
        </div>

        {/* Help Request Info */}
        {ticket.helpRequestDescription && (
          <div className={styles.helpRequest}>
            <div className={styles.helpRequestHeader}>
              <i className="fas fa-hands-helping"></i>
              <h4>Yêu Cầu Hỗ Trợ</h4>
            </div>
            <p className={styles.helpRequestDescription}>{ticket.helpRequestDescription}</p>
            {ticket.helpRequestedAt && (
              <p className={styles.helpRequestTime}>
                <i className="fas fa-clock"></i>
                Yêu cầu lúc: {new Date(ticket.helpRequestedAt).toLocaleString('vi-VN')}
              </p>
            )}
          </div>
        )}

        {/* Available Staff List */}
        <div className={styles.staffSection}>
          <div className={styles.sectionHeader}>
            <h4>
              <i className="fas fa-users"></i>
              Chọn Người Hỗ Trợ ({selectedHelpers.length} người được chọn)
            </h4>
            <p className={styles.sectionHint}>
              Bạn có thể chọn nhiều người để hỗ trợ cùng lúc
            </p>
          </div>

          <div className={styles.staffList}>
            {availableStaff.map((staff) => {
              const isSelected = selectedHelpers.includes(staff.id);
              const isAssignee = staff.id === ticket.assigneeId;

              return (
                <div
                  key={staff.id}
                  className={`${styles.staffCard} ${isSelected ? styles.staffCardSelected : ''} ${
                    isAssignee ? styles.staffCardDisabled : ''
                  }`}
                  onClick={() => !isAssignee && toggleHelper(staff.id)}
                >
                  {/* Selection Checkbox */}
                  <div className={styles.staffCheckbox}>
                    {isAssignee ? (
                      <i className="fas fa-ban" title="Người xử lý chính"></i>
                    ) : (
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => {}}
                        disabled={isAssignee}
                      />
                    )}
                  </div>

                  {/* Avatar */}
                  <div className={styles.staffAvatar}>{staff.avatar}</div>

                  {/* Staff Info */}
                  <div className={styles.staffInfo}>
                    <div className={styles.staffName}>
                      {staff.name}
                      {isAssignee && (
                        <span className={styles.assigneeBadge}>
                          <i className="fas fa-user-check"></i> Người xử lý chính
                        </span>
                      )}
                    </div>
                    <div className={styles.staffMeta}>
                      <span className={styles.staffDepartment}>
                        <i className="fas fa-building"></i> {staff.department}
                      </span>
                      <span className={styles.staffWorkload}>
                        <i className="fas fa-tasks"></i> {staff.currentTickets} tickets
                      </span>
                      {getAvailabilityBadge(staff.availability)}
                    </div>
                    <div className={styles.staffSkills}>
                      {staff.skills.slice(0, 3).map((skill, index) => (
                        <span key={index} className={styles.skillBadge}>
                          {skill}
                        </span>
                      ))}
                      {staff.skills.length > 3 && (
                        <span className={styles.skillBadge}>+{staff.skills.length - 3}</span>
                      )}
                    </div>
                  </div>

                  {/* Selection Indicator */}
                  {isSelected && (
                    <div className={styles.selectedIndicator}>
                      <i className="fas fa-check-circle"></i>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className={styles.errorMessage}>
            <i className="fas fa-exclamation-triangle"></i>
            {error}
          </div>
        )}

        {/* Summary */}
        {selectedHelpers.length > 0 && (
          <div className={styles.summary}>
            <i className="fas fa-info-circle"></i>
            <p>
              Bạn đang phân công <strong>{selectedHelpers.length}</strong> người để hỗ trợ ticket
              này. Họ sẽ nhận được thông báo ngay lập tức.
            </p>
          </div>
        )}

        {/* Actions */}
        <div className={styles.actions}>
          <Button
            type="button"
            variant="secondary"
            onClick={handleClose}
            disabled={submitting}
            fullWidth
          >
            Hủy
          </Button>
          <Button
            type="submit"
            variant="primary"
            disabled={submitting || selectedHelpers.length === 0}
            fullWidth
          >
            {submitting ? (
              <>
                <i className="fas fa-spinner fa-spin"></i> Đang phân công...
              </>
            ) : (
              <>
                <i className="fas fa-user-plus"></i> Phân Công ({selectedHelpers.length} người)
              </>
            )}
          </Button>
        </div>
      </form>
    </Modal>
  );
};

export default SupportAssignmentModal;
