import React from 'react';
import { Card } from '../../common/Card';
import { ActivityItem } from '../../../models/Dashboard';
import styles from './RecentActivity.module.css';

export interface RecentActivityProps {
  activities: ActivityItem[];
}

export const RecentActivity: React.FC<RecentActivityProps> = ({ activities }) => {
  return (
    <Card className={styles.recentActivity}>
      <div className={styles.header}>
        <h3 className={styles.title}>
          <i className="fas fa-history"></i> Hoạt Động Gần Đây
        </h3>
      </div>
      <div className={styles.activityList}>
        {activities.map((activity) => (
          <div key={activity.id} className={styles.activityItem}>
            <div
              className={`${styles.dot} ${styles[activity.color]}`}
              aria-hidden="true"
            ></div>
            <div className={styles.activityContent}>
              <div className={styles.activityTitle}>{activity.title}</div>
              <div className={styles.activitySubtitle}>{activity.subtitle}</div>
              <div className={styles.activityTime}>{activity.timeAgo}</div>
            </div>
          </div>
        ))}
      </div>
    </Card>
  );
};
