/**
 * Custom hook for fetching and managing task detail data
 */

import { useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { fetchTaskById } from '../../../store/slices/tasksSlice';
import { Task } from '../../../models/Task';

interface UseTaskDetailReturn {
  task: Task | null;
  loading: boolean;
  error: string | null;
}

/**
 * Hook to fetch and manage task detail data
 * @param taskId - Task ID to fetch
 * @returns Task data, loading state, and error
 */
export const useTaskDetail = (taskId: string | undefined): UseTaskDetailReturn => {
  const dispatch = useAppDispatch();
  const { selectedTask, loading, error } = useAppSelector((state) => state.tasks);

  useEffect(() => {
    if (taskId) {
      dispatch(fetchTaskById(taskId));
    }
  }, [dispatch, taskId]);

  return {
    task: selectedTask,
    loading,
    error: error || null,
  };
};
