import { UUID, Timestamps } from './common';

export interface Attachment extends Timestamps {
  id: UUID;
  ticketId: UUID;
  fileName: string;
  fileSize: number; // in bytes
  fileType: string; // MIME type
  fileUrl: string;
  uploadedById: UUID;
  uploadedByName: string;
}

export interface UploadAttachmentRequest {
  ticketId: UUID;
  file: File;
}

export enum AttachmentFileType {
  Image = 'image',
  PDF = 'pdf',
  Document = 'document',
  Other = 'other',
}

export const getFileTypeFromMime = (mimeType: string): AttachmentFileType => {
  if (mimeType.startsWith('image/')) {
    return AttachmentFileType.Image;
  }
  if (mimeType === 'application/pdf') {
    return AttachmentFileType.PDF;
  }
  if (
    mimeType.includes('word') ||
    mimeType.includes('document') ||
    mimeType.includes('spreadsheet') ||
    mimeType.includes('presentation')
  ) {
    return AttachmentFileType.Document;
  }
  return AttachmentFileType.Other;
};

export const getFileIcon = (fileType: AttachmentFileType): string => {
  switch (fileType) {
    case AttachmentFileType.Image:
      return 'fas fa-image';
    case AttachmentFileType.PDF:
      return 'fas fa-file-pdf';
    case AttachmentFileType.Document:
      return 'fas fa-file-word';
    default:
      return 'fas fa-file';
  }
};

export const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
};
