import React from 'react';
import styles from './TicketStatsCards.module.css';

export interface TicketStats {
  total: number;
  submitted: number;
  inProgress: number;
  resolved: number;
  closed: number;
}

export interface TicketStatsCardsProps {
  stats: TicketStats;
  loading?: boolean;
}

export const TicketStatsCards: React.FC<TicketStatsCardsProps> = ({ stats, loading }) => {
  if (loading) {
    return (
      <div className={styles.grid}>
        {[...Array(5)].map((_, i) => (
          <div key={i} className={`${styles.card} ${styles.skeleton}`}>
            <div className={styles.skeletonLabel} />
            <div className={styles.skeletonValue} />
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className={styles.grid}>
      <div className={styles.card}>
        <div className={styles.label}>Tất cả</div>
        <div className={`${styles.value} ${styles.total}`}>{stats.total}</div>
      </div>

      <div className={styles.card}>
        <div className={styles.label}>Submitted</div>
        <div className={`${styles.value} ${styles.submitted}`}>{stats.submitted}</div>
      </div>

      <div className={styles.card}>
        <div className={styles.label}>In Progress</div>
        <div className={`${styles.value} ${styles.inProgress}`}>{stats.inProgress}</div>
      </div>

      <div className={styles.card}>
        <div className={styles.label}>Đã xử lý</div>
        <div className={`${styles.value} ${styles.resolved}`}>{stats.resolved}</div>
      </div>

      <div className={styles.card}>
        <div className={styles.label}>Closed</div>
        <div className={`${styles.value} ${styles.closed}`}>{stats.closed}</div>
      </div>
    </div>
  );
};
