import { apiClient } from './api';
import { User } from '../models/User';
import { getMockUsers, getMockUserById, getMockCurrentUser } from '../mocks';

// Use mock data in development when API is not available
import { USE_MOCK_DATA } from '../config/appSettings';

/**
 * Simulate network delay for more realistic mock behavior
 */
const mockDelay = (ms = 200): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, ms));
};

export const userService = {
  /**
   * Get all users (for dropdowns, assignments)
   */
  async getUsers(): Promise<User[]> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      return getMockUsers();
    }

    return apiClient.get<User[]>('/users');
  },

  /**
   * Get user by ID
   */
  async getUserById(id: string): Promise<User> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const user = getMockUserById(id);
      if (!user) {
        throw new Error(`User ${id} not found`);
      }
      return user;
    }

    return apiClient.get<User>(`/users/${id}`);
  },

  /**
   * Get current logged-in user
   */
  async getCurrentUser(): Promise<User> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      return getMockCurrentUser();
    }

    return apiClient.get<User>('/users/me');
  },

  /**
   * Get users by department
   */
  async getUsersByDepartment(departmentId: string): Promise<User[]> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      return getMockUsers().filter((u) => u.departmentId === departmentId);
    }

    return apiClient.get<User[]>(`/users?departmentId=${departmentId}`);
  },
};
