import React, { useState } from 'react';
import { Modal } from '../../../components/common/Modal';
import { Button } from '../../../components/common/Button';
import styles from './WorkflowModal.module.css';

interface ApproveTaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (rating: number) => Promise<void>;
  taskTitle: string;
}

export const ApproveTaskModal: React.FC<ApproveTaskModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  taskTitle,
}) => {
  const [rating, setRating] = useState<number>(5);
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    setSubmitting(true);
    try {
      await onSubmit(rating);
      handleClose();
    } catch (error) {
      console.error('Failed to approve task:', error);
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setRating(5);
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={handleClose} title="Duyệt task hoàn thành" size="md">
      <form onSubmit={handleSubmit} className={styles.form}>
        <div className={styles.taskInfo}>
          <span className={styles.label}>Task:</span>
          <span className={styles.value}>{taskTitle}</span>
        </div>

        <div className={styles.successAlert}>
          <i className="fas fa-check-circle"></i>
          <span>Task sẽ được đánh dấu là hoàn thành sau khi duyệt</span>
        </div>

        <div className={styles.formGroup}>
          <label className={styles.label}>
            Đánh giá chất lượng <span className={styles.required}>*</span>
          </label>
          <div className={styles.ratingGroup}>
            {[1, 2, 3, 4, 5].map((star) => (
              <button
                key={star}
                type="button"
                className={`${styles.starButton} ${rating >= star ? styles.active : ''}`}
                onClick={() => setRating(star)}
                disabled={submitting}
              >
                <i className={rating >= star ? 'fas fa-star' : 'far fa-star'}></i>
              </button>
            ))}
            <span className={styles.ratingText}>
              {rating === 1 && 'Kém'}
              {rating === 2 && 'Trung bình'}
              {rating === 3 && 'Khá'}
              {rating === 4 && 'Tốt'}
              {rating === 5 && 'Xuất sắc'}
            </span>
          </div>
        </div>

        <div className={styles.actions}>
          <Button type="button" variant="secondary" onClick={handleClose} disabled={submitting}>
            Hủy
          </Button>
          <Button type="submit" variant="success" disabled={submitting}>
            {submitting ? 'Đang duyệt...' : 'Duyệt task'}
          </Button>
        </div>
      </form>
    </Modal>
  );
};
