import { apiClient } from './api';
import { Ticket, TicketFilter, TicketStatus } from '../models/Ticket';
import { PaginatedResponse, UUID } from '../models/common';
import {
  getMockTickets,
  getMockTicketById,
  mockTickets,
} from '../mocks/tickets.mock';
import { getMockUserById } from '../mocks/users.mock';

// Use mock data in development when API is not available
import { USE_MOCK_DATA } from '../config/appSettings';

/**
 * Simulate network delay for more realistic mock behavior
 */
const mockDelay = (ms = 300): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, ms));
};

export const ticketService = {
  /**
   * Get paginated list of tickets with optional filters
   */
  async getTickets(
    filters?: TicketFilter,
    page = 1,
    pageSize = 20
  ): Promise<PaginatedResponse<Ticket>> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      return getMockTickets({
        priority: filters?.priority,
        status: filters?.status,
        search: filters?.search,
        page,
        pageSize,
      });
    }

    const queryParams = new URLSearchParams({
      page: page.toString(),
      pageSize: pageSize.toString(),
      ...(filters?.priority && { priority: filters.priority }),
      ...(filters?.status && { status: filters.status }),
      ...(filters?.departmentId && { departmentId: filters.departmentId }),
      ...(filters?.assigneeId && { assigneeId: filters.assigneeId }),
      ...(filters?.slaStatus && { slaStatus: filters.slaStatus }),
      ...(filters?.search && { search: filters.search }),
    });

    return apiClient.get<PaginatedResponse<Ticket>>(
      `/tickets?${queryParams.toString()}`
    );
  },

  /**
   * Get a single ticket by ID
   */
  async getTicketById(id: string): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const ticket = getMockTicketById(id);
      if (!ticket) {
        throw new Error(`Ticket ${id} not found`);
      }
      return ticket;
    }

    return apiClient.get<Ticket>(`/tickets/${id}`);
  },

  /**
   * Create a new ticket
   */
  async createTicket(data: Partial<Ticket>): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const newTicket: Ticket = {
        id: `TKT-${String(mockTickets.length + 1).padStart(3, '0')}` as UUID,
        title: data.title || '',
        description: data.description || '',
        priority: data.priority!,
        status: TicketStatus.New,
        departmentId: data.departmentId!,
        departmentName: data.departmentName || '',
        assigneeId: null,
        assigneeName: null,
        createdById: 'user-1' as UUID, // Mock current user
        createdByName: 'Đinh Bộ Lĩnh',
        dueDate: data.dueDate || new Date(),
        sla: {
          targetDate: new Date(),
          remainingMinutes: 0,
          percentage: 0,
          status: 'safe' as any,
          breached: false,
        },
        tags: data.tags || [],
        attachmentCount: 0,
        commentCount: 0,
        createdAt: new Date(),
        updatedAt: new Date(),
      };
      mockTickets.unshift(newTicket);
      return newTicket;
    }

    return apiClient.post<Ticket>('/tickets', data);
  },

  /**
   * Update an existing ticket
   */
  async updateTicket(id: string, data: Partial<Ticket>): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === id);
      if (index === -1) {
        throw new Error(`Ticket ${id} not found`);
      }
      mockTickets[index] = {
        ...mockTickets[index],
        ...data,
        updatedAt: new Date(),
      };
      return mockTickets[index];
    }

    return apiClient.put<Ticket>(`/tickets/${id}`, data);
  },

  /**
   * Delete a ticket
   */
  async deleteTicket(id: string): Promise<void> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === id);
      if (index !== -1) {
        mockTickets.splice(index, 1);
      }
      return;
    }

    return apiClient.delete<void>(`/tickets/${id}`);
  },

  /**
   * Assign a ticket to a user
   */
  async assignTicket(ticketId: string, assigneeId: string): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === ticketId);
      if (index === -1) {
        throw new Error(`Ticket ${ticketId} not found`);
      }
      const user = getMockUserById(assigneeId);
      if (!user) {
        throw new Error(`User ${assigneeId} not found`);
      }
      mockTickets[index] = {
        ...mockTickets[index],
        assigneeId: assigneeId as UUID,
        assigneeName: user.fullName,
        updatedAt: new Date(),
      };
      return mockTickets[index];
    }

    return apiClient.post<Ticket>(`/tickets/${ticketId}/assign`, {
      assigneeId,
    });
  },

  /**
   * Update ticket status
   */
  async updateStatus(ticketId: string, status: string): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === ticketId);
      if (index === -1) {
        throw new Error(`Ticket ${ticketId} not found`);
      }
      mockTickets[index] = {
        ...mockTickets[index],
        status: status as TicketStatus,
        updatedAt: new Date(),
      };
      return mockTickets[index];
    }

    return apiClient.patch<Ticket>(`/tickets/${ticketId}/status`, { status });
  },

  /**
   * Triage a ticket (Accept, Reject, or Request More Info)
   */
  async triageTicket(
    ticketId: string,
    action: 'accept' | 'reject' | 'request_info',
    priority?: string,
    reason?: string
  ): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === ticketId);
      if (index === -1) {
        throw new Error(`Ticket ${ticketId} not found`);
      }

      let newStatus: TicketStatus;
      const updates: Partial<Ticket> = {
        updatedAt: new Date(),
        triagedAt: new Date(),
      };

      switch (action) {
        case 'accept':
          newStatus = TicketStatus.Triaged;
          updates.status = newStatus;
          break;
        case 'reject':
          newStatus = TicketStatus.Rejected;
          updates.status = newStatus;
          updates.rejectionReason = reason || '';
          break;
        case 'request_info':
          newStatus = TicketStatus.Pending;
          updates.status = newStatus;
          updates.pendingReason = reason || '';
          break;
        default:
          throw new Error(`Invalid triage action: ${action}`);
      }

      if (priority) {
        updates.priority = priority as any;
      }

      mockTickets[index] = {
        ...mockTickets[index],
        ...updates,
      };

      return mockTickets[index];
    }

    return apiClient.patch<Ticket>(`/tickets/${ticketId}/triage`, {
      action,
      priority,
      reason,
    });
  },

  /**
   * Request help on a ticket
   */
  async requestHelp(
    ticketId: string,
    description: string,
    suggestedHelperId?: string
  ): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === ticketId);
      if (index === -1) {
        throw new Error(`Ticket ${ticketId} not found`);
      }

      mockTickets[index] = {
        ...mockTickets[index],
        status: TicketStatus.HelpRequested,
        helpRequestDescription: description,
        helpRequestedAt: new Date(),
        updatedAt: new Date(),
      };

      return mockTickets[index];
    }

    return apiClient.post<Ticket>(`/tickets/${ticketId}/request-help`, {
      description,
      suggestedHelperId,
    });
  },

  /**
   * Assign a helper to a ticket
   */
  async assignHelper(ticketId: string, helperId: string): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === ticketId);
      if (index === -1) {
        throw new Error(`Ticket ${ticketId} not found`);
      }

      const helper = getMockUserById(helperId);
      if (!helper) {
        throw new Error(`User ${helperId} not found`);
      }

      const currentUser = getMockUserById('user-2'); // Mock manager
      const newHelper = {
        id: `helper-${Date.now()}` as UUID,
        userId: helper.id,
        userName: helper.fullName,
        assignedAt: new Date(),
        assignedById: currentUser!.id,
        assignedByName: currentUser!.fullName,
      };

      mockTickets[index] = {
        ...mockTickets[index],
        status: TicketStatus.SupportAssigned,
        helpers: [...(mockTickets[index].helpers || []), newHelper],
        updatedAt: new Date(),
      };

      return mockTickets[index];
    }

    return apiClient.post<Ticket>(`/tickets/${ticketId}/assign-helper`, {
      helperId,
    });
  },

  /**
   * Assign multiple helpers to a ticket (Manager action for help request)
   */
  async assignTicketSupport(
    ticketId: string,
    helpers: { userId: string; userName: string }[]
  ): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === ticketId);
      if (index === -1) {
        throw new Error(`Ticket ${ticketId} not found`);
      }

      const currentUser = getMockUserById('user-2'); // Mock manager
      const newHelpers = helpers.map((helper, i) => ({
        id: `helper-${Date.now()}-${i}` as UUID,
        userId: helper.userId as UUID,
        userName: helper.userName,
        assignedAt: new Date(),
        assignedById: currentUser!.id,
        assignedByName: currentUser!.fullName,
      }));

      mockTickets[index] = {
        ...mockTickets[index],
        status: TicketStatus.SupportAssigned,
        helpers: [...(mockTickets[index].helpers || []), ...newHelpers],
        updatedAt: new Date(),
      };

      return mockTickets[index];
    }

    return apiClient.post<Ticket>(`/tickets/${ticketId}/assign-support`, {
      helpers,
    });
  },

  /**
   * Remove a helper from a ticket
   */
  async removeHelper(ticketId: string, helperId: string): Promise<Ticket> {
    if (USE_MOCK_DATA) {
      await mockDelay();
      const index = mockTickets.findIndex((t) => t.id === ticketId);
      if (index === -1) {
        throw new Error(`Ticket ${ticketId} not found`);
      }

      const helpers = (mockTickets[index].helpers || []).filter(
        (h) => h.id !== helperId
      );

      mockTickets[index] = {
        ...mockTickets[index],
        helpers,
        // If no helpers left, revert to HelpRequested status
        status: helpers.length === 0 ? TicketStatus.HelpRequested : mockTickets[index].status,
        updatedAt: new Date(),
      };

      return mockTickets[index];
    }

    return apiClient.delete<Ticket>(`/tickets/${ticketId}/helpers/${helperId}`);
  },
};
