import { UUID, Timestamps } from './common';
import { TicketStatus, TicketPriority } from './Ticket';

export interface TicketActivity extends Timestamps {
  id: UUID;
  ticketId: UUID;
  type: ActivityType;
  userId: UUID;
  userName: string;
  userAvatar?: string;
  description: string;
  metadata?: ActivityMetadata;
}

export enum ActivityType {
  Created = 'created',
  StatusChanged = 'status_changed',
  PriorityChanged = 'priority_changed',
  Assigned = 'assigned',
  Reassigned = 'reassigned',
  Unassigned = 'unassigned',
  CommentAdded = 'comment_added',
  AttachmentAdded = 'attachment_added',
  AttachmentRemoved = 'attachment_removed',
  SLAWarning = 'sla_warning',
  SLABreached = 'sla_breached',
  HelpRequested = 'help_requested',
  HelperAssigned = 'helper_assigned',
  HelperRemoved = 'helper_removed',
  Resolved = 'resolved',
  Closed = 'closed',
  Reopened = 'reopened',
}

export interface ActivityMetadata {
  oldValue?: string | TicketStatus | TicketPriority;
  newValue?: string | TicketStatus | TicketPriority;
  assigneeId?: UUID;
  assigneeName?: string;
  commentId?: UUID;
  attachmentId?: UUID;
  attachmentName?: string;
  [key: string]: any;
}

export const getActivityIcon = (type: ActivityType): string => {
  switch (type) {
    case ActivityType.Created:
      return 'fas fa-plus-circle';
    case ActivityType.StatusChanged:
      return 'fas fa-exchange-alt';
    case ActivityType.PriorityChanged:
      return 'fas fa-exclamation-triangle';
    case ActivityType.Assigned:
    case ActivityType.Reassigned:
      return 'fas fa-user-plus';
    case ActivityType.Unassigned:
      return 'fas fa-user-minus';
    case ActivityType.CommentAdded:
      return 'fas fa-comment';
    case ActivityType.AttachmentAdded:
      return 'fas fa-paperclip';
    case ActivityType.AttachmentRemoved:
      return 'fas fa-trash';
    case ActivityType.SLAWarning:
      return 'fas fa-clock';
    case ActivityType.SLABreached:
      return 'fas fa-exclamation-circle';
    case ActivityType.HelpRequested:
      return 'fas fa-hands-helping';
    case ActivityType.HelperAssigned:
      return 'fas fa-user-check';
    case ActivityType.HelperRemoved:
      return 'fas fa-user-times';
    case ActivityType.Resolved:
      return 'fas fa-check-circle';
    case ActivityType.Closed:
      return 'fas fa-lock';
    case ActivityType.Reopened:
      return 'fas fa-redo';
    default:
      return 'fas fa-info-circle';
  }
};

export const getActivityColor = (type: ActivityType): string => {
  switch (type) {
    case ActivityType.Created:
      return 'var(--success-color)';
    case ActivityType.StatusChanged:
    case ActivityType.Assigned:
    case ActivityType.Reassigned:
      return 'var(--primary-color)';
    case ActivityType.PriorityChanged:
    case ActivityType.SLAWarning:
      return 'var(--warning-color)';
    case ActivityType.SLABreached:
    case ActivityType.AttachmentRemoved:
    case ActivityType.Unassigned:
      return 'var(--danger-color)';
    case ActivityType.Resolved:
    case ActivityType.Closed:
      return 'var(--success-color)';
    case ActivityType.HelpRequested:
    case ActivityType.HelperAssigned:
      return 'var(--info-color)';
    default:
      return 'var(--gray-500)';
  }
};
