import React from 'react';
import { CategoryDistributionItem } from '../../../models/Statistics';
import { Card } from '../../common/Card';
import styles from './CategoryDistribution.module.css';

interface CategoryDistributionProps {
  data: CategoryDistributionItem[];
}

export const CategoryDistribution: React.FC<CategoryDistributionProps> = ({ data }) => {
  return (
    <Card className={styles.distributionCard}>
      <h3 className={styles.title}>
        <i className="fas fa-tags" style={{ color: 'var(--info-color)' }}></i>
        Phân bố theo loại công việc
      </h3>
      <div className={styles.categoryList}>
        {data.map((category) => (
          <div key={category.name} className={styles.categoryItem}>
            <div className={styles.categoryHeader}>
              <span className={styles.categoryName}>{category.name}</span>
              <span className={styles.categoryValue}>
                {category.count} ({category.percentage}%)
              </span>
            </div>
            <div className={styles.progressBar}>
              <div
                className={styles.progressFill}
                style={{
                  width: `${category.percentage}%`,
                  backgroundColor: category.color,
                }}
              ></div>
            </div>
          </div>
        ))}
      </div>
    </Card>
  );
};
