/**
 * Mock Activity Heatmap Data
 * Generates activity data for each hour (0-23) and day (0-6: Sun-Sat)
 */
const mockActivityHeatmap: ActivityHeatmapData[] = [];
for (let day = 0; day < 7; day++) {
  for (let hour = 0; hour < 24; hour++) {
    // Simulate realistic work patterns (higher during work hours 8-17)
    let value = 0;
    if (day >= 1 && day <= 5) {
      // Weekdays
      if (hour >= 8 && hour <= 17) {
        value = Math.floor(Math.random() * 5) + 2; // 2-6 tasks
      } else if (hour >= 7 && hour <= 19) {
        value = Math.floor(Math.random() * 2); // 0-1 tasks
      }
    } else {
      // Weekends - minimal activity
      if (hour >= 8 && hour <= 17) {
        value = Math.floor(Math.random() * 2); // 0-1 tasks
      }
    }
    mockActivityHeatmap.push({ hour, day, value });
  }
}

