import React from 'react';
import { PersonalGoal } from '../../../models/Statistics';
import { Card } from '../../common/Card';
import { GoalCard } from '../GoalCard';
import styles from './PersonalGoals.module.css';

interface PersonalGoalsProps {
  goals: PersonalGoal[];
  achievementRate: number;
}

export const PersonalGoals: React.FC<PersonalGoalsProps> = ({
  goals,
  achievementRate,
}) => {
  return (
    <Card className={styles.goalsCard}>
      <div className={styles.header}>
        <h3 className={styles.title}>
          <i className="fas fa-bullseye" style={{ color: 'var(--primary-color)' }}></i>
          Mục Tiêu Cá Nhân
        </h3>
        <div className={styles.achievementRate}>
          <span className={styles.rateLabel}>Tỷ lệ đạt:</span>
          <span className={styles.rateValue}>{achievementRate.toFixed(1)}%</span>
        </div>
      </div>
      <div className={styles.goalsList}>
        {goals.map((goal) => (
          <GoalCard key={goal.id} goal={goal} />
        ))}
      </div>
      {goals.length === 0 && (
        <div className={styles.emptyState}>
          <i className="fas fa-target"></i>
          <p>Chưa có mục tiêu nào</p>
          <button className={styles.addButton}>
            <i className="fas fa-plus"></i> Tạo Mục Tiêu
          </button>
        </div>
      )}
    </Card>
  );
};
