import React, { useEffect, useState } from 'react';
import { useAppDispatch, useAppSelector } from '../../../../store/hooks';
import { fetchTicketById, requestHelp, assignTicketSupport, removeHelper } from '../../../../store/slices/ticketsSlice';
import { addToast } from '../../../../store/slices/uiSlice';
import { UUID } from '../../../../models/common';
import { TicketStatus } from '../../../../models/Ticket';
import { UserRole } from '../../../../models/User';
import { Button } from '../../../../components/common/Button';
import { SLABadge, formatSLATime, getSLAStatus } from '../../../../components/common/SLABadge';
import { StatusBadge } from '../../../../components/common/StatusBadge';
import { TriageTicketModal } from '../../../../components/tickets/TriageTicketModal';
import RequestHelpModal from '../RequestHelpModal';
import SupportAssignmentModal from '../../../../components/tickets/SupportAssignmentModal';
import TicketHelpersDisplay from './TicketHelpersDisplay';
import styles from './TicketDetailSlideout.module.css';

export interface TicketDetailSlideoutProps {
  ticketId: UUID;
  onEdit: () => void;
  onClose: () => void;
}

export const TicketDetailSlideout: React.FC<TicketDetailSlideoutProps> = ({
  ticketId,
  onEdit,
  onClose,
}) => {
  const dispatch = useAppDispatch();
  const ticket = useAppSelector((state) => state.tickets.selectedTicket);
  const currentUser = useAppSelector((state) => state.auth.user);
  const [loading, setLoading] = useState(true);
  const [isTriageModalOpen, setIsTriageModalOpen] = useState(false);
  const [isRequestHelpModalOpen, setIsRequestHelpModalOpen] = useState(false);
  const [isSupportAssignmentModalOpen, setIsSupportAssignmentModalOpen] = useState(false);

  useEffect(() => {
    const loadTicket = async () => {
      try {
        setLoading(true);
        await dispatch(fetchTicketById(ticketId)).unwrap();
      } catch (error) {
        dispatch(
          addToast({
            message: 'Không thể tải thông tin phiếu',
            type: 'error',
          })
        );
        onClose();
      } finally {
        setLoading(false);
      }
    };

    loadTicket();
  }, [dispatch, ticketId, onClose]);

  if (loading) {
    return (
      <div className={styles.loading}>
        <div className={styles.spinner}></div>
        <span>Đang tải dữ liệu...</span>
      </div>
    );
  }

  if (!ticket) {
    return (
      <div className={styles.error}>
        <i className="fas fa-exclamation-triangle"></i>
        <span>Không tìm thấy thông tin phiếu</span>
      </div>
    );
  }

  const getPriorityLabel = (priority: string) => {
    switch (priority.toLowerCase()) {
      case 'emergency':
        return 'Khẩn cấp';
      case 'high':
        return 'Cao';
      case 'medium':
        return 'Trung bình';
      case 'low':
        return 'Thấp';
      default:
        return priority;
    }
  };

  const slaStatus = getSLAStatus(ticket.sla.percentage, ticket.sla.breached);
  const slaTime = formatSLATime(ticket.sla.remainingMinutes);

  const canEdit = ticket.status !== TicketStatus.Closed;
  const canTriage =
    currentUser &&
    (currentUser.role === UserRole.Manager || currentUser.role === UserRole.Admin) &&
    (ticket.status === TicketStatus.Submitted || ticket.status === TicketStatus.Pending);
  
  const canRequestHelp =
    currentUser &&
    currentUser.role === UserRole.Staff &&
    ticket.assigneeId === currentUser.id &&
    ticket.status === TicketStatus.InProgress;
  
  const canAssignHelper =
    currentUser &&
    (currentUser.role === UserRole.Manager || currentUser.role === UserRole.Admin) &&
    ticket.status === TicketStatus.HelpRequested;

  const handleTriageSuccess = () => {
    dispatch(fetchTicketById(ticketId));
  };
  
  const handleRequestHelp = async (description: string) => {
    try {
      await dispatch(requestHelp({ ticketId, description })).unwrap();
      dispatch(addToast({ message: 'Yêu cầu hỗ trợ đã được gửi thành công', type: 'success' }));
      await dispatch(fetchTicketById(ticketId));
    } catch (error) {
      throw error;
    }
  };
  
  const handleAssignSupport = async (helpers: { userId: UUID; userName: string }[]) => {
    try {
      await dispatch(assignTicketSupport({ ticketId, helpers })).unwrap();
      dispatch(addToast({ 
        message: `Đã phân công ${helpers.length} người hỗ trợ thành công`, 
        type: 'success' 
      }));
      await dispatch(fetchTicketById(ticketId));
    } catch (error) {
      throw error;
    }
  };
  
  const handleRemoveHelper = async (helperId: UUID) => {
    try {
      await dispatch(removeHelper({ ticketId, helperId })).unwrap();
      dispatch(addToast({ message: 'Người hỗ trợ đã được xóa', type: 'success' }));
      await dispatch(fetchTicketById(ticketId));
    } catch (error) {
      dispatch(addToast({ message: 'Có lỗi xảy ra khi xóa người hỗ trợ', type: 'error' }));
    }
  };

  return (
    <div className={styles.container}>
      {/* Header */}
      <div className={styles.header}>
        <div className={styles.headerTop}>
          <div className={styles.ticketCode}>
            <i className="fas fa-ticket-alt"></i>
            <span>#{ticket.id.substring(0, 8)}</span>
          </div>
          <div className={styles.headerActions}>
            {canRequestHelp && (
              <Button size="sm" variant="warning" onClick={() => setIsRequestHelpModalOpen(true)}>
                <i className="fas fa-hands-helping"></i>
                Yêu Cầu Hỗ Trợ
              </Button>
            )}
            {canAssignHelper && (
              <Button size="sm" variant="warning" onClick={() => setIsSupportAssignmentModalOpen(true)}>
                <i className="fas fa-user-plus"></i>
                Phân Công Hỗ Trợ
              </Button>
            )}
            {canTriage && (
              <Button size="sm" variant="warning" onClick={() => setIsTriageModalOpen(true)}>
                <i className="fas fa-tasks"></i>
                Phân Loại
              </Button>
            )}
            {canEdit && (
              <Button size="sm" variant="primary" onClick={onEdit}>
                <i className="fas fa-edit"></i>
                Chỉnh sửa
              </Button>
            )}
          </div>
        </div>
        <h2 className={styles.title}>{ticket.title}</h2>
      </div>

      {/* Content */}
      <div className={styles.content}>
        {/* Status Cards */}
        <div className={styles.statusGrid}>
          <div className={styles.statusCard}>
            <span className={styles.statusLabel}>Trạng thái</span>
            <StatusBadge status={ticket.status} />
          </div>

          <div className={styles.statusCard}>
            <span className={styles.statusLabel}>Độ ưu tiên</span>
            <span className={`${styles.priority} ${styles[`priority-${ticket.priority.toLowerCase()}`]}`}>
              {getPriorityLabel(ticket.priority)}
            </span>
          </div>

          <div className={styles.statusCard}>
            <span className={styles.statusLabel}>SLA</span>
            <SLABadge status={slaStatus} timeRemaining={slaTime} />
          </div>
        </div>

        {/* Details Grid */}
        <div className={styles.section}>
          <h3 className={styles.sectionTitle}>Thông tin chi tiết</h3>
          <div className={styles.detailsGrid}>
            <div className={styles.detailItem}>
              <span className={styles.detailLabel}>
                <i className="fas fa-building"></i>
                Phòng ban
              </span>
              <span className={styles.detailValue}>{ticket.departmentName}</span>
            </div>

            <div className={styles.detailItem}>
              <span className={styles.detailLabel}>
                <i className="fas fa-user"></i>
                Người tạo
              </span>
              <span className={styles.detailValue}>{ticket.createdByName}</span>
            </div>

            <div className={styles.detailItem}>
              <span className={styles.detailLabel}>
                <i className="fas fa-user-check"></i>
                Người xử lý
              </span>
              <span className={styles.detailValue}>
                {ticket.assigneeName || <em className={styles.unassigned}>Chưa gán</em>}
              </span>
            </div>

            <div className={styles.detailItem}>
              <span className={styles.detailLabel}>
                <i className="fas fa-calendar"></i>
                Ngày tạo
              </span>
              <span className={styles.detailValue}>
                {new Date(ticket.createdAt).toLocaleString('vi-VN')}
              </span>
            </div>

            <div className={styles.detailItem}>
              <span className={styles.detailLabel}>
                <i className="fas fa-clock"></i>
                Cập nhật cuối
              </span>
              <span className={styles.detailValue}>
                {new Date(ticket.updatedAt).toLocaleString('vi-VN')}
              </span>
            </div>

            <div className={styles.detailItem}>
              <span className={styles.detailLabel}>
                <i className="fas fa-hourglass-end"></i>
                Hạn xử lý
              </span>
              <span className={styles.detailValue}>
                {new Date(ticket.dueDate).toLocaleString('vi-VN')}
              </span>
            </div>
          </div>
        </div>

        {/* Description */}
        <div className={styles.section}>
          <h3 className={styles.sectionTitle}>Mô tả</h3>
          <div className={styles.description}>{ticket.description}</div>
        </div>

        {/* Helpers Display */}
        {currentUser && (
          <TicketHelpersDisplay
            ticket={ticket}
            currentUserRole={currentUser.role}
            onRemoveHelper={handleRemoveHelper}
          />
        )}

        {/* Attachments */}
        {ticket.attachmentCount > 0 && (
          <div className={styles.section}>
            <h3 className={styles.sectionTitle}>
              <i className="fas fa-paperclip"></i>
              Tệp đính kèm ({ticket.attachmentCount})
            </h3>
            <div className={styles.attachments}>
              <p className={styles.placeholder}>
                <i className="fas fa-info-circle"></i>
                Danh sách tệp đính kèm sẽ được hiển thị ở đây
              </p>
            </div>
          </div>
        )}

        {/* Comments */}
        {ticket.commentCount > 0 && (
          <div className={styles.section}>
            <h3 className={styles.sectionTitle}>
              <i className="fas fa-comments"></i>
              Bình luận ({ticket.commentCount})
            </h3>
            <div className={styles.comments}>
              <p className={styles.placeholder}>
                <i className="fas fa-info-circle"></i>
                Danh sách bình luận sẽ được hiển thị ở đây
              </p>
            </div>
          </div>
        )}

        {/* Activity Timeline */}
        <div className={styles.section}>
          <h3 className={styles.sectionTitle}>
            <i className="fas fa-history"></i>
            Lịch sử hoạt động
          </h3>
          <div className={styles.timeline}>
            <div className={styles.timelineItem}>
              <div className={styles.timelineDot}></div>
              <div className={styles.timelineContent}>
                <div className={styles.timelineHeader}>
                  <span className={styles.timelineAction}>Tạo phiếu</span>
                  <span className={styles.timelineTime}>
                    {new Date(ticket.createdAt).toLocaleString('vi-VN')}
                  </span>
                </div>
                <span className={styles.timelineUser}>bởi {ticket.createdByName}</span>
              </div>
            </div>
            
            {ticket.assigneeId && (
              <div className={styles.timelineItem}>
                <div className={styles.timelineDot}></div>
                <div className={styles.timelineContent}>
                  <div className={styles.timelineHeader}>
                    <span className={styles.timelineAction}>Phân công xử lý</span>
                    <span className={styles.timelineTime}>
                      {new Date(ticket.updatedAt).toLocaleString('vi-VN')}
                    </span>
                  </div>
                  <span className={styles.timelineUser}>cho {ticket.assigneeName}</span>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Triage Modal */}
      <TriageTicketModal
        isOpen={isTriageModalOpen}
        ticketId={ticketId}
        onClose={() => setIsTriageModalOpen(false)}
        onSuccess={handleTriageSuccess}
      />
      
      {/* Request Help Modal */}
      {ticket && (
        <RequestHelpModal
          isOpen={isRequestHelpModalOpen}
          ticket={ticket}
          onClose={() => setIsRequestHelpModalOpen(false)}
          onSubmit={handleRequestHelp}
        />
      )}
      
      {/* Support Assignment Modal */}
      {ticket && (
        <SupportAssignmentModal
          isOpen={isSupportAssignmentModalOpen}
          ticket={ticket}
          onClose={() => setIsSupportAssignmentModalOpen(false)}
          onSubmit={handleAssignSupport}
        />
      )}
    </div>
  );
};
