import React from 'react';
import { Button } from '../../../../components/common/Button';
import styles from './ProgressCard.module.css';

interface ProgressCardProps {
  progress: number;
  onProgressChange: (value: number) => void;
  onUpdate: () => void;
  isUpdating?: boolean;
}

export const ProgressCard: React.FC<ProgressCardProps> = ({
  progress,
  onProgressChange,
  onUpdate,
  isUpdating = false,
}) => {
  const handleDecrease = () => {
    const newValue = Math.max(0, progress - 5);
    onProgressChange(newValue);
  };

  const handleIncrease = () => {
    const newValue = Math.min(100, progress + 5);
    onProgressChange(newValue);
  };

  return (
    <div className={styles.progressCard}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>Tiến Độ</h3>
      </div>
      <div className={styles.cardBody}>
        <div className={styles.progressDisplay}>
          {progress}%
        </div>
        
        <div className={styles.sliderContainer}>
          <input
            type="range"
            min="0"
            max="100"
            value={progress}
            onChange={(e) => onProgressChange(Number(e.target.value))}
            className={styles.progressSlider}
            aria-label="Progress slider"
          />
          <div className={styles.sliderLabels}>
            <span>0%</span>
            <span>100%</span>
          </div>
        </div>

        <div className={styles.buttonGroup}>
          <Button
            variant="secondary"
            size="sm"
            onClick={handleDecrease}
            disabled={progress === 0 || isUpdating}
            className={styles.stepButton}
          >
            -5%
          </Button>
          <Button
            variant="primary"
            size="sm"
            onClick={onUpdate}
            disabled={isUpdating}
            className={styles.updateButton}
          >
            {isUpdating ? (
              <>
                <i className="fas fa-spinner fa-spin"></i> Đang cập nhật...
              </>
            ) : (
              'Cập nhật'
            )}
          </Button>
          <Button
            variant="secondary"
            size="sm"
            onClick={handleIncrease}
            disabled={progress === 100 || isUpdating}
            className={styles.stepButton}
          >
            +5%
          </Button>
        </div>
      </div>
    </div>
  );
};
