/**
 * Custom hook for managing task progress updates
 */

import { useEffect, useState } from 'react';
import { useAppDispatch } from '../../../store/hooks';
import { updateTask } from '../../../store/slices/tasksSlice';
import { Task, TaskStatus } from '../../../models/Task';

interface UseProgressUpdateReturn {
  progress: number;
  setProgress: (value: number) => void;
  handleUpdateProgress: () => Promise<void>;
  handleSubmitForReview: () => Promise<void>;
  isUpdating: boolean;
}

/**
 * Hook to manage task progress tracking
 * @param task - Current task object
 * @returns Progress state and update handlers
 */
export const useProgressUpdate = (task: Task | null): UseProgressUpdateReturn => {
  const dispatch = useAppDispatch();
  const [progress, setProgress] = useState(0);
  const [isUpdating, setIsUpdating] = useState(false);

  // Sync local progress state with task progress
  useEffect(() => {
    if (task) {
      setProgress(task.progress);
    }
  }, [task]);

  /**
   * Update task progress
   */
  const handleUpdateProgress = async () => {
    if (!task) return;

    setIsUpdating(true);
    try {
      await dispatch(
        updateTask({
          id: task.id,
          data: { progress },
        })
      ).unwrap();
    } catch (error) {
      console.error('Failed to update progress:', error);
    } finally {
      setIsUpdating(false);
    }
  };

  /**
   * Submit task for review (set status to under_review and progress to 100%)
   */
  const handleSubmitForReview = async () => {
    if (!task) return;

    setIsUpdating(true);
    try {
      await dispatch(
        updateTask({
          id: task.id,
          data: { 
            status: TaskStatus.UnderReview, 
            progress: 100 
          },
        })
      ).unwrap();
    } catch (error) {
      console.error('Failed to submit for review:', error);
    } finally {
      setIsUpdating(false);
    }
  };

  return {
    progress,
    setProgress,
    handleUpdateProgress,
    handleSubmitForReview,
    isUpdating,
  };
};
