import React from 'react';
import { UUID } from '../../../../../models/common';
import { ActivityType, getActivityIcon, getActivityColor } from '../../../../../models/Activity';
import styles from './ActivityTab.module.css';

interface ActivityTabProps {
  ticketId: UUID;
}

interface ActivityItem {
  id: string;
  type: ActivityType;
  userName: string;
  description: string;
  timestamp: Date;
}

const ActivityTab: React.FC<ActivityTabProps> = () => {
  // Mock activity data
  const activities: ActivityItem[] = [
    {
      id: '1',
      type: ActivityType.Created,
      userName: 'Nguyễn Văn A',
      description: 'Ticket được tạo',
      timestamp: new Date('2024-03-24T10:15:00'),
    },
    {
      id: '2',
      type: ActivityType.Assigned,
      userName: 'Manager A',
      description: 'Đã gán cho Linh Dinh',
      timestamp: new Date('2024-03-24T10:20:00'),
    },
    {
      id: '3',
      type: ActivityType.StatusChanged,
      userName: 'Linh Dinh',
      description: 'Trạng thái: Assigned → In Progress',
      timestamp: new Date('2024-03-24T10:30:00'),
    },
    {
      id: '4',
      type: ActivityType.SLAWarning,
      userName: 'System',
      description: '⚠️ SLA Warning: Còn 30 phút đến hạn SLA',
      timestamp: new Date('2024-03-24T10:45:00'),
    },
  ];

  const formatTimestamp = (date: Date) => {
    return date.toLocaleString('vi-VN', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <div className={styles.container}>
      <div className={styles.timeline}>
        {activities.map((activity) => (
          <div key={activity.id} className={styles.timelineItem}>
            <div 
              className={styles.timelineMarker}
              style={{ backgroundColor: getActivityColor(activity.type) }}
            >
              <i className={getActivityIcon(activity.type)}></i>
            </div>
            <div className={styles.timelineContent}>
              <div className={styles.description}>{activity.description}</div>
              <div className={styles.meta}>
                bởi <strong>{activity.userName}</strong>
              </div>
              <div className={styles.timestamp}>{formatTimestamp(activity.timestamp)}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ActivityTab;
