import React from 'react';
import { SLAStats } from '../../../models/SLAAlert';
import './AlertsStatsCards.css';

interface AlertsStatsCardsProps {
  stats: SLAStats | null;
  loading?: boolean;
}

export const AlertsStatsCards: React.FC<AlertsStatsCardsProps> = ({ stats, loading }) => {
  if (loading || !stats) {
    return (
      <div className="alerts-stats">
        <div className="alerts-stats__card alerts-stats__card--loading">
          <div className="alerts-stats__skeleton"></div>
        </div>
        <div className="alerts-stats__card alerts-stats__card--loading">
          <div className="alerts-stats__skeleton"></div>
        </div>
        <div className="alerts-stats__card alerts-stats__card--loading">
          <div className="alerts-stats__skeleton"></div>
        </div>
        <div className="alerts-stats__card alerts-stats__card--loading">
          <div className="alerts-stats__skeleton"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="alerts-stats">
      <div className="alerts-stats__card alerts-stats__card--breached">
        <div className="alerts-stats__icon">🚨</div>
        <div className="alerts-stats__content">
          <div className="alerts-stats__label">Vi phạm SLA</div>
          <div className="alerts-stats__value">{stats.breached}</div>
        </div>
      </div>

      <div className="alerts-stats__card alerts-stats__card--danger">
        <div className="alerts-stats__icon">⚠️</div>
        <div className="alerts-stats__content">
          <div className="alerts-stats__label">Nguy cơ cao</div>
          <div className="alerts-stats__value">{stats.danger}</div>
        </div>
      </div>

      <div className="alerts-stats__card alerts-stats__card--warning">
        <div className="alerts-stats__icon">⏰</div>
        <div className="alerts-stats__content">
          <div className="alerts-stats__label">Cảnh báo</div>
          <div className="alerts-stats__value">{stats.warning}</div>
        </div>
      </div>

      <div className="alerts-stats__card alerts-stats__card--watch">
        <div className="alerts-stats__icon">👁️</div>
        <div className="alerts-stats__content">
          <div className="alerts-stats__label">Theo dõi</div>
          <div className="alerts-stats__value">{stats.watch}</div>
        </div>
      </div>
    </div>
  );
};
